    hwHint:["Иероглифыг хуруугаараа зураад, доороос зөвийг нь сонго.","Draw a character, then pick the right one below.","Нарисуйте иероглиф пальцем и выберите верный вариант ниже.","指で文字を描き、下から正しいものを選んでください。"],
