    pyHint:["Дарахад дуу гарна. Кирилл бичлэг нь ойролцоо (Палладиус), жинхэнэ дуудлагыг 🔊-оор сонсож давтана.","Tap to hear it. Cyrillic is approximate (Palladius style); trust the audio.","Нажмите, чтобы услышать. Кириллица приблизительна (по Палладию); ориентируйтесь на 🔊 и повторяйте.","タップすると音が出ます。キリル表記は近似（パラディウス式）です。実際の発音は🔊で聞いて繰り返してください。"],
