  /* зочдод зориулсан шууд холбоос: …/#hsk эсвэл …/#gram (#guest = HSK үгийн сан) */
  function hashTab(){var h=(location.hash||'').replace('#','');if(h==='hsk'||h==='gram'||h==='cards'||h==='play'||h==='media'||h==='words')showTab(h);else if(h==='guest')showTab('hsk')}
  hashTab();window.addEventListener('hashchange',hashTab);

  /* ---------- Бичлэг · Дуу (media): хадмал дээрх үгийг товшиж сурах ---------- */
  var MED={items:null,loading:null,kind:'feed',cur:null,sel:'',quiz:null,t:-1,muted:true,pin:true,obs:null};
  function mediaLoad(force){
    if(MED.items&&!force)return Promise.resolve(MED.items);
    if(MED.loading&&!force)return MED.loading;
    MED.loading=(async function(){
      var out=[];
      var fl=['data/media.json','data/media-auto.json','data/stories.json'];
      for(var fi=0;fi<fl.length;fi++){try{var r=await fetch(fl[fi]);if(r.ok){var j=await r.json();(j.items||[]).forEach(function(x){x.local=1;out.push(x)})}}catch(e){}}
      if(sb){try{
        var x=await sb.from('media').select('*').order('created_at',{ascending:false});
        if(!x.error)(x.data||[]).forEach(function(d){out.unshift({id:d.id,kind:d.kind,level:d.level,title:d.title,titleZh:d.title_zh,srcType:d.src_type,src:d.src,lines:d.lines||[]})});
      }catch(e){}}
      MED.items=out;return out;
    })();
    return MED.loading;
  }
  /* Хятад текстийг HSK үгсэд хуваана (хамгийн урт таарсан үг) */
  function segZh(s){
    if(!HSKD)HSKD=buildD(HSKRAW);
    var out=[],i=0,a=Array.from(String(s||''));
    while(i<a.length){
      var done=false;
      if(/[一-鿿]/.test(a[i])){
        for(var n=Math.min(6,a.length-i);n>=1;n--){
          var w=a.slice(i,i+n).join('');
          if(HSKD[w]){out.push({h:w});i+=n;done=true;break}
        }
      }
      if(!done){out.push({t:a[i]});i++}
    }
    return out;
  }
  function mediaWords(it){
    var seen={},o=[];
    (it.lines||[]).forEach(function(ln){segZh(ln.zh).forEach(function(x){
      if(!x.h||seen[x.h])return;seen[x.h]=1;
      var hit=hskLookup(x.h);o.push({h:x.h,l:hit.l,p:hP(x.h,hit.p),m:hM(x.h)});
    })});
    return o.sort(function(a,b){return a.l-b.l});
  }
  function haveSet(){var s={};wordsArr().forEach(function(w){s[w.h]=1});return s}
  function ytId(u){var m=/(?:youtu\.be\/|v=|embed\/|shorts\/)([\w-]{11})/.exec(u||'');return m?m[1]:(/^[\w-]{11}$/.test(u||'')?u:'')}
  function mediaPlayer(it){
    if(it.srcType==='youtube'&&ytId(it.src))return '<div class="mplay"><iframe src="https://www.youtube-nocookie.com/embed/'+esc(ytId(it.src))+'" title="'+esc(it.title)+'" loading="lazy" referrerpolicy="strict-origin-when-cross-origin" allow="encrypted-media; picture-in-picture" allowfullscreen></iframe></div>';
    if(it.srcType==='file'&&/^(media|video)\/[^\/\\<>"'?#]+$/.test(it.src||'')){
      var au=/\.(mp3|m4a|wav|ogg)$/i.test(it.src);
      return '<'+(au?'audio class="maud"':'video class="mvid"')+' id="mVid" controls playsinline preload="metadata" src="'+esc(encodeURI(it.src))+'"></'+(au?'audio':'video')+'>';
    }
    return '';
  }
  function renderMedia(){
    var box=$('mBody');if(!box)return;
    mediaLoad().then(function(items){
      var it=MED.cur&&items.filter(function(x){return x.id===MED.cur})[0];
      $('mKinds').hidden=!!it;
      if(!it){MED.cur=null;renderMediaList(items);return}
      renderMediaItem(it);
    });
  }
  function renderMediaList(items){
    var k=MED.kind;
    if(k==='feed'&&!MED.userK&&!feedItems(items).length)k=MED.kind='world';
    $('mKinds').innerHTML=['feed','news','world','video','text'].map(function(x){return '<button class="chip" type="button" data-mk="'+x+'" aria-pressed="'+(k===x)+'">'+T(x==='feed'?'mFeed':x==='news'?'mNews':x==='world'?'mWorld':x==='video'?'mVideo':x==='text'?'mText':'mSong')+'</button>'}).join('');
    if(k==='feed'){renderMediaFeed(items);return}
    if(k==='song')k=MED.kind='feed';
    if(k==='world'||k==='news'){renderWorldFeed();return}
    mediaStop();
    if(k==='text'){renderTextReader();return}
    var L=items.filter(function(x){return x.kind===k}),hv=haveSet();
    $('mBody').innerHTML=L.length?'<div class="list">'+L.map(function(x){
      var ws=mediaWords(x),nw=ws.filter(function(w){return !hv[w.h]&&w.m}).length;
      return '<button class="card mcard" type="button" data-mi="'+esc(x.id)+'"><div class="between"><b>'+esc(x.title)+'</b>'+(x.level?'<span class="badge">HSK '+x.level+'</span>':'')+'</div>'+
        (x.titleZh?'<span class="m" lang="zh">'+esc(x.titleZh)+'</span>':'')+(x.auto?'<span class="hint">🤖 '+esc(T('mAuto'))+'</span>':'')+(x.story?'<span class="hint">🎬</span>':'')+'<span class="hint">'+esc(T('mMeta',{n:(x.lines||[]).length,w:nw}))+'</span></button>';
    }).join('')+'</div>':'<div class="empty">'+T('mEmpty')+'</div>';
  }
  /* ---- Өөрийн текст уншигч: хуулсан хятад текстийн үг бүрийг дарж утга харна ---- */
  /* ---- 🔔 Өдрийн сануулга (Web Push) ---- */
  var VAPID_PUB='BADT9Ve7dvTVMXKVfX1_JzJL_eP-xDNTzcJTbWa_toaXtrFRpW9S64b_J5zNcLNt-Kkf0oJ3BlsrLf1kOYl04ZA';   /* GitHub Pages дээр ажиллуулахдаа: npx web-push generate-vapid-keys → public key-г энд тавина */
  function pushOk(){return !!(VAPID_PUB&&'serviceWorker' in navigator&&'PushManager' in window&&'Notification' in window&&sb&&uid)}
  function b64u(b){var p='='.repeat((4-b.length%4)%4),r=(b+p).replace(/-/g,'+').replace(/_/g,'/'),raw=atob(r),o=new Uint8Array(raw.length);for(var i=0;i<raw.length;i++)o[i]=raw.charCodeAt(i);return o}
  function pushTime(){var v=(($('pushHour')&&$('pushHour').value)||'20:00').split(':'),h=parseInt(v[0],10),m=parseInt(v[1],10);return {h:isNaN(h)?20:h,m:isNaN(m)?0:m}}
  function pushHour(){return pushTime().h}
  function pushFreq(){if(!isPrem())return 1;var v=parseInt($('pushFreq')&&$('pushFreq').value,10);return isNaN(v)?1:Math.max(1,Math.min(6,v))}
  function pushTxt(){var t=pushTime();return (t.h<10?'0':'')+t.h+':'+(t.m<10?'0':'')+t.m}
  function pushRow(sub){var j=sub.toJSON(),k=j.keys||{};return {endpoint:sub.endpoint,uid:uid,p256dh:k.p256dh,auth:k.auth,hour:pushHour(),minute:pushTime().m,freq:pushFreq(),tzo:-new Date().getTimezoneOffset(),lang:lang}}
  function pushRender(){
    var box=$('pushBox');if(!box)return;
    var ios=/iPhone|iPad|iPod/.test(navigator.userAgent)&&!window.matchMedia('(display-mode: standalone)').matches&&!navigator.standalone;
    if(!VAPID_PUB||!uid||!('serviceWorker' in navigator)){box.hidden=true;return}
    box.hidden=false;
    var fs=$('pushFreq');if(fs&&!fs.options.length){[1,2,3,4,6].forEach(function(n){var o=document.createElement('option');o.value=n;o.textContent=T('pushFreqN',{n:n})+(PREM.cfg.on&&n>1?' 💎':'');fs.appendChild(o)});try{fs.value=localStorage.getItem('hsk-push-f')||'1'}catch(e){}}
    var hs=$('pushHour');if(hs&&!hs.dataset.init){hs.dataset.init='1';var sv='20:00';try{sv=localStorage.getItem('hsk-push-h')||sv}catch(e){}if(/^\d+$/.test(sv))sv=(sv.length<2?'0':'')+sv+':00';hs.value=sv}
    var btn=$('pushBtn'),hint=$('pushHint');
    if(!('PushManager' in window)||!('Notification' in window)){hint.textContent=ios?T('pushHintIos'):T('pushErr');btn.hidden=true;return}
    btn.hidden=false;
    if(Notification.permission==='denied'){hint.textContent=T('pushHintDenied');btn.hidden=true;return}
    navigator.serviceWorker.ready.then(function(reg){return reg.pushManager.getSubscription()}).then(function(sub){
      btn.dataset.on=sub?'1':'';btn.textContent=T(sub?'pushOff':'pushOn');
      hint.textContent=sub?T('pushHintOn',{h:pushTxt()}):T('pushHintOff');
    }).catch(function(){hint.textContent=T('pushHintOff')});
  }
  function pushToggle(){
    var btn=$('pushBtn');if(!pushOk()){toast(T('pushErr')+' [ok:'+(!!VAPID_PUB)+(('serviceWorker' in navigator)?'':' nosw')+(('PushManager' in window)?'':' nopush')+(('Notification' in window)?'':' nonotif')+(sb?'':' nosb')+(uid?'':' nouid')+']');return}
    navigator.serviceWorker.ready.then(function(reg){
      return reg.pushManager.getSubscription().then(function(sub){
        if(sub){ /* унтраах */
          var ep=sub.endpoint;return sub.unsubscribe().then(function(){return sb.from('push_subs').delete().eq('endpoint',ep)});
        }
        return Notification.requestPermission().then(function(p){
          if(p!=='granted')throw new Error('denied');
          return reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:b64u(VAPID_PUB)});
        }).then(function(ns){
          try{localStorage.setItem('hsk-push-h',pushTxt());localStorage.setItem('hsk-push-f',String(pushFreq()))}catch(e){}
          return sb.from('push_subs').upsert(pushRow(ns)).then(function(r){if(r.error)throw r.error});
        });
      });
    }).then(pushRender).catch(function(e){var m=e&&(e.name==='Error'?e.message:(e.name||'')+(e.message?': '+e.message:''))||String(e);toast(T('pushErr')+' ['+String(m).slice(0,90)+']');pushRender()});
  }
  document.addEventListener('click',function(e){if(e.target.closest&&e.target.closest('#pushBtn'))pushToggle()});
  document.addEventListener('change',function(e){
    if(!e.target||(e.target.id!=='pushHour'&&e.target.id!=='pushFreq'))return;
    if(e.target.id==='pushFreq'&&!isPrem()&&+e.target.value>1){e.target.value='1';toast(T('prNeed'),'think');return}
    try{localStorage.setItem('hsk-push-h',pushTxt());localStorage.setItem('hsk-push-f',String(pushFreq()))}catch(x){}
    if(!pushOk())return;
    navigator.serviceWorker.ready.then(function(reg){return reg.pushManager.getSubscription()}).then(function(sub){
      if(sub)return sb.from('push_subs').update({hour:pushHour(),minute:pushTime().m,freq:pushFreq(),tzo:-new Date().getTimezoneOffset(),lang:lang}).eq('endpoint',sub.endpoint)}).then(pushRender).catch(function(){});
  });
  /* ---------- Premium: эрх · хүсэлт · админ ---------- */
  function isPrem(){return !PREM.cfg.on||isOwner||!!(PREM.until&&PREM.until>=TODAY)}
  async function premLoad(){
    if(!sb||!uid)return;
    try{
      var r=await Promise.all([sb.from('premium').select('until').eq('uid',uid).maybeSingle(),
        sb.from('premium_requests').select('*').eq('uid',uid).order('id',{ascending:false}).limit(5),
        sb.from('site').select('notice').eq('id','prem').maybeSingle()]);
      PREM.until=(r[0].data&&r[0].data.until)||'';PREM.reqs=r[1].data||[];
      var c={};try{c=JSON.parse((r[2].data&&r[2].data.notice)||'{}')}catch(e){}
      PREM.cfg={on:!!c.on,info:String(c.info||''),prices:Object.assign({'30':'','90':'','365':''},c.prices||{})};
    }catch(e){}
  }
  function premLock(){return '<div class="card prlock"><h2>'+esc(T('prLockT'))+'</h2><p>'+esc(T('prLockD'))+'</p><button class="btn" type="button" data-prgo="1">'+esc(T('prOpen'))+'</button></div>'}
  var premPlan='90';
  function premRender(){
    var c=$('premCard');if(!c)return;
    if(!uid||(!PREM.cfg.on&&!isOwner)){c.hidden=true;return}
    c.hidden=false;
    var has=PREM.until&&PREM.until>=TODAY,pr=PREM.cfg.prices;
    var h='<div class="between"><h2>'+esc(T('prTitle'))+'</h2><span class="badge prb'+(has?' on':'')+'">'+(has?esc(T('prUntil',{d:PREM.until})):'Free')+'</span></div>';
    if(!PREM.cfg.on)h+='<div class="hint">'+esc(T('prOffNote'))+'</div>';
    h+='<ul class="prlist">'+T('prPerks').split('|').map(function(x){return '<li>'+esc(x)+'</li>'}).join('')+'</ul><div class="prplans">'+
      ['30','90','365'].map(function(n){return '<button type="button" class="chip" data-prplan="'+n+'" aria-pressed="'+(premPlan===n?'true':'false')+'"><b>'+esc(T('prPlan'+n))+'</b>'+(pr[n]?'<br><small>'+esc(pr[n])+'</small>':'')+'</button>'}).join('')+'</div>';
    if(PREM.cfg.info)h+='<div class="label">'+esc(T('prPayHdr'))+'</div><div class="prpay">'+esc(PREM.cfg.info)+'</div>';
    h+='<div class="row"><input type="text" id="prRef" maxlength="160" placeholder="'+esc(T('prRefPh'))+'" style="flex:1;min-width:140px"><button class="btn" type="button" data-prsend="1">'+esc(T('prSend'))+'</button></div>';
    if(PREM.reqs.length)h+='<div class="hint">'+PREM.reqs.map(function(r){return esc(T('prPlan'+r.plan))+' · '+esc(String(r.created_at).slice(0,10))+' · '+esc(T(r.status==='pending'?'prPend':r.status==='approved'?'prOk':'prNo'))}).join('<br>')+'</div>';
    var keep=$('prRef')&&$('prRef').value;c.innerHTML=h;if(keep)$('prRef').value=keep;
  }
  document.addEventListener('click',function(e){
    var t=e.target.closest&&e.target.closest('[data-prplan],[data-prsend],[data-prgo]');if(!t)return;
    if(t.dataset.prplan){premPlan=t.dataset.prplan;premRender();return}
    if(t.dataset.prgo){showTab('me');setTimeout(function(){var c=$('premCard');if(c&&!c.hidden)c.scrollIntoView({behavior:'smooth',block:'start'})},60);return}
    var ref=($('prRef').value||'').trim();if(!ref){toast(T('prNeedRef'),'oops');return}
    if(!sb||!uid)return;t.disabled=true;
    sb.from('premium_requests').insert({uid:uid,plan:premPlan,ref:ref.slice(0,160)}).then(function(x){
      if(x.error){toast(T('tSaveErr'),'oops');t.disabled=false;return}
      $('prRef').value='';toast(T('prSent'),'cheer');return premLoad().then(premRender)});
  });
  function addDaysIso(s,n){var d=parseIso(s);d.setDate(d.getDate()+n);return iso(d)}
  async function premAdminLoad(){
    if(!isOwner||!sb)return;var box=$('premAdmin');if(!box)return;
    try{
      var r=await Promise.all([sb.from('premium_requests').select('*').eq('status','pending').order('id'),sb.from('premium').select('*')]);
      PREM.pend=r[0].data||[];PREM.act={};(r[1].data||[]).forEach(function(x){PREM.act[x.uid]=x.until});
    }catch(e){}
    premAdminRender();
  }
  function nickOf(id){return (P[id]&&P[id].nick)||id.slice(0,8)}
  function premAdminRender(){
    var box=$('premAdmin');if(!box||!isOwner)return;
    var cf=PREM.cfg,pr=cf.prices,focus=document.activeElement&&box.contains(document.activeElement);
    if(focus&&document.activeElement.id!=='paGrantBtn')return; // бичиж байхад дарж бичихгүй
    var users=Object.keys(P).sort(function(a,b){return nickOf(a).localeCompare(nickOf(b))});
    var act=Object.keys(PREM.act).filter(function(k){return PREM.act[k]>=TODAY});
    box.innerHTML='<h2>💎 Premium удирдлага</h2>'+
      '<label class="row" style="gap:8px"><input type="checkbox" id="paOn"'+(cf.on?' checked':'')+'> <span>Хаалт идэвхтэй (унтраалттай бол бүгд үнэгүй ашиглана)</span></label>'+
      '<textarea id="paInfo" rows="4" maxlength="600" placeholder="Төлбөрийн заавар: банк, дансны дугаар, нэр, гүйлгээний утга...">'+esc(cf.info)+'</textarea>'+
      '<div class="row"><input type="text" id="pa30" maxlength="24" placeholder="30 хоног: үнэ" value="'+esc(pr['30'])+'"><input type="text" id="pa90" maxlength="24" placeholder="90 хоног: үнэ" value="'+esc(pr['90'])+'"><input type="text" id="pa365" maxlength="24" placeholder="1 жил: үнэ" value="'+esc(pr['365'])+'"></div>'+
      '<button class="btn" type="button" id="paSave">Хадгалах</button>'+
      '<div class="label" style="margin-top:14px">Хүлээгдэж буй хүсэлт ('+PREM.pend.length+')</div>'+
      (PREM.pend.length?PREM.pend.map(function(r){return '<div class="adm"><div class="between"><b>'+esc(nickOf(r.uid))+'</b><span class="badge">'+esc(T('prPlan'+r.plan))+'</span></div><div class="hint">'+esc(r.ref)+' · '+esc(String(r.created_at).slice(0,10))+'</div><div class="row"><button class="btn small" type="button" data-paok="'+r.id+'">Зөвшөөрөх</button><button class="btn ghost small" type="button" data-pano="'+r.id+'">Татгалзах</button></div></div>'}).join(''):'<div class="empty">Хүсэлт алга</div>')+
      '<div class="label" style="margin-top:14px">Гараар олгох</div><div class="row"><select id="paUser">'+users.map(function(k){return '<option value="'+esc(k)+'">'+esc(nickOf(k))+'</option>'}).join('')+'</select><select id="paDays"><option value="30">30 хоног</option><option value="90">90 хоног</option><option value="365">1 жил</option></select><button class="btn small" type="button" id="paGrantBtn">Олгох</button></div>'+
      '<div class="hint">Идэвхтэй Premium ('+act.length+'): '+esc(act.map(function(k){return nickOf(k)+' → '+PREM.act[k]}).join(', ')||'—')+'</div>';
  }
  async function premGrant(id,days,reqId){
    var base=PREM.act[id]&&PREM.act[id]>=TODAY?PREM.act[id]:TODAY,until=addDaysIso(base,+days);
    var x=await sb.from('premium').upsert({uid:id,until:until,plan:String(days),updated_at:new Date().toISOString()});if(x.error)throw x.error;
    if(reqId){x=await sb.from('premium_requests').update({status:'approved'}).eq('id',reqId);if(x.error)throw x.error}
    PREM.act[id]=until;
  }
  document.addEventListener('click',function(e){
    var b=e.target.closest&&e.target.closest('#premAdmin button');if(!b||!isOwner||!sb)return;
    var done=function(m){toast(m||'✓','cheer');premAdminLoad()},fail=function(){toast(T('tSaveErr'),'oops')};
    if(b.id==='paSave'){
      PREM.cfg={on:$('paOn').checked,info:$('paInfo').value.trim(),prices:{'30':$('pa30').value.trim(),'90':$('pa90').value.trim(),'365':$('pa365').value.trim()}};
      sb.from('site').upsert({id:'prem',notice:JSON.stringify(PREM.cfg)}).then(function(x){x.error?fail():done()});
    }else if(b.dataset.paok){
      var r=PREM.pend.filter(function(x){return String(x.id)===b.dataset.paok})[0];if(!r)return;
      premGrant(r.uid,r.plan,r.id).then(function(){done()}).catch(fail);
    }else if(b.dataset.pano){
      sb.from('premium_requests').update({status:'rejected'}).eq('id',b.dataset.pano).then(function(x){x.error?fail():done()});
    }else if(b.id==='paGrantBtn'){
      var u=$('paUser').value;if(u)premGrant(u,$('paDays').value,null).then(function(){done()}).catch(fail);
    }
  });
  var TXF={c:300,n:3};
  function txUse(inc){var k='hsk-txq',d=TODAY,c=0;try{var v=(localStorage.getItem(k)||'').split('|');if(v[0]===d)c=+v[1]||0;if(inc){c++;localStorage.setItem(k,d+'|'+c)}}catch(e){}return c}
  function txGet(){if(MED.tx==null){try{MED.tx=localStorage.getItem('hsk-text')||''}catch(e){MED.tx=''}}return MED.tx}
  function txSet(v){MED.tx=v;try{localStorage.setItem('hsk-text',v)}catch(e){}}
  function renderTextReader(){
    var box=$('mBody');if(!box)return;
    box.innerHTML='<div class="card txcard"><div class="hint">'+esc(T('txHint'))+'</div>'+
      '<textarea id="txIn" class="txin" lang="zh" maxlength="2000" placeholder="'+esc(T('txPh'))+'" spellcheck="false"></textarea>'+
      '<div class="row"><button class="btn small" type="button" data-txgo>'+esc(T('txGo'))+'</button> <button class="btn small ghost" type="button" data-txclr>'+esc(T('txClr'))+'</button></div></div>'+
      '<div id="txOut"></div>';
    $('txIn').value=txGet();
    if(txGet().trim())renderTextOut();
  }
  document.addEventListener('input',function(e){if(e.target&&e.target.id==='txIn')txSet(e.target.value)});
  function renderTextOut(){
    var out=$('txOut');if(!out)return;
    var t=txGet().trim();
    if(!t){out.innerHTML='';return}
    var cut=false;if(!isPrem()&&t.length>TXF.c){t=t.slice(0,TXF.c);cut=true}
    var hv=haveSet(),nw=mediaWords({lines:[{zh:t}]}).filter(function(w){return !hv[w.h]&&w.m});
    var body=t.split(/\n+/).map(function(l){return '<p>'+zhRuby(l,hv,'mfw')+'</p>'}).join('');
    out.innerHTML='<div class="card txres"><div class="between"><span class="hint">'+esc(nw.length?T('txNew',{n:nw.length}):T('txNone'))+'</span>'+
      (nw.length?'<button class="btn small" type="button" data-txadd>'+esc(T('txAdd'))+'</button>':'')+'</div>'+
      '<div class="wzh txbody" lang="zh">'+body+'</div>'+(isPrem()?'':'<div class="hint">'+esc(T('prTxLim',{c:TXF.c,n:TXF.n}))+'</div>')+'</div><div class="card mfcard" id="wfCard" hidden></div>';
  }
  function renderMediaItem(it){
    var hv=haveSet(),ws=mediaWords(it),nw=ws.filter(function(w){return !hv[w.h]&&w.m});
    var lines=(it.lines||[]).map(function(ln,i){
      var z=segZh(ln.zh).map(function(x){return x.h?'<button type="button" class="mw'+(hv[x.h]?' has':'')+'" data-h="'+esc(x.h)+'" lang="zh">'+esc(x.h)+'</button>':esc(x.t)}).join('');
      return '<div class="mline" data-li="'+i+'"'+(ln.t!=null?' data-t="'+ln.t+'"':'')+'><div class="zh" lang="zh">'+z+'</div>'+(ln.mn?'<div class="m">'+esc(ln.mn)+'</div>':'')+'</div>';
    }).join('');
    $('mBody').innerHTML='<div class="card"><div class="between"><button class="btn ghost small" type="button" id="mBack">←</button><span class="badge">'+(it.level?'HSK '+it.level:'')+'</span></div>'+
      '<h2>'+esc(it.title)+'</h2>'+(it.titleZh?'<div class="m" lang="zh">'+esc(it.titleZh)+'</div>':'')+mediaPlayer(it)+'<div class="hint">'+esc(T('mTapHint'))+'</div></div>'+
      '<div class="card" id="mWord" hidden></div>'+
      '<div class="card"><div class="mlines">'+(lines||'<div class="empty">'+T('mNoLines')+'</div>')+'</div></div>'+
      '<div class="card"><div class="between"><h3>'+esc(T('mNew',{n:nw.length}))+'</h3>'+(nw.length?'<button class="btn small" type="button" id="mAddAll">'+esc(T('mAddAll'))+'</button>':'')+'</div>'+
      (nw.length?'<div class="list">'+nw.map(function(w){return '<div class="w"><span class="h" lang="zh">'+esc(w.h)+'</span><span><span class="p">'+esc(w.p)+'</span><br><span class="m">'+esc(w.m)+'</span></span><span class="badge">HSK '+w.l+'</span><button class="btn small ghost" type="button" data-ma="'+esc(w.h)+'">+</button></div>'}).join('')+'</div>':'<div class="empty">'+T('mAllKnown')+'</div>')+
      (ws.length>=4?'<button class="btn" type="button" id="mQuizBtn">'+esc(T('mQuiz'))+'</button>':'')+'<div id="mQuiz"></div></div>';
    var v=$('mVid');
    if(v&&(it.lines||[]).some(function(l){return l.t!=null}))v.addEventListener('timeupdate',function(){
      var cur=-1;(it.lines||[]).forEach(function(l,i){if(l.t!=null&&l.t<=v.currentTime)cur=i});
      document.querySelectorAll('.mline').forEach(function(e){e.classList.toggle('on',+e.dataset.li===cur)});
    });
  }
  function mediaAdd(h){
    if(haveSet()[h])return false;
    var hit=hskLookup(h);if(!hit)return false;var m=hM(h);if(!m)return false;
    addWord(h,hP(h,hit.p),m,'',TODAY,hit.l);return true;
  }
  function mediaWordCard(h){
    var hit=hskLookup(h),has=haveSet()[h],m=hM(h);
    var b=$('mWord');b.hidden=false;
    b.innerHTML='<div class="between"><span class="h big" lang="zh">'+esc(h)+'</span><span class="badge">HSK '+hit.l+'</span></div><div class="p">'+esc(hP(h,hit.p))+'</div><div class="m">'+esc(m||'—')+'</div>'+
      '<div class="row"><button class="btn ghost small" type="button" data-msp="'+esc(h)+'">🔊</button>'+(has?'<span class="hint">'+esc(T('mHave'))+'</span>':(m?'<button class="btn small" type="button" data-ma="'+esc(h)+'">+ '+esc(T('mAddOne'))+'</button>':''))+'</div>';
    b.scrollIntoView({block:'nearest',behavior:'smooth'});
  }
  function mediaQuiz(it){
    var ws=mediaWords(it).filter(function(w){return w.m});
    var pool=ws.slice().sort(function(){return Math.random()-.5}).slice(0,8);
    var all=Object.keys(HSKD||buildD(HSKRAW));
    function wrong(ex){var o=[],g=0;while(o.length<3&&g++<400){var h=all[Math.floor(Math.random()*all.length)],m=hM(h);if(m&&m!==ex&&o.indexOf(m)<0)o.push(m)}return o}
    MED.quiz={q:pool.map(function(w){var opts=wrong(w.m).concat([w.m]).sort(function(){return Math.random()-.5});return {w:w,opts:opts}}),i:0,ok:0};
    renderMediaQuiz();
  }
  function renderMediaQuiz(){
    var Q=MED.quiz,box=$('mQuiz');if(!Q||!box)return;
    if(Q.i>=Q.q.length){box.innerHTML='<div class="card"><h3>'+esc(T('mScore',{a:Q.ok,b:Q.q.length}))+'</h3><button class="btn small" type="button" id="mQuizBtn2">'+esc(T('exAgain'))+'</button></div>';return}
    var x=Q.q[Q.i];
    box.innerHTML='<div class="card"><div class="hint">'+(Q.i+1)+'/'+Q.q.length+'</div><div class="h big" lang="zh">'+esc(x.w.h)+'</div><div class="p">'+esc(x.w.p)+'</div><div class="list">'+
      x.opts.map(function(o){return '<button class="btn ghost" type="button" data-mo="'+esc(o)+'">'+esc(o)+'</button>'}).join('')+'</div></div>';
  }

  /* TikTok маягийн босоо лент: богино бичлэг автоматаар тоглож, хадмал цагтай гарч, үг дээр дарж сурна */
  /* ---------- 🌍 Дэлхий: улс орон · сансар · түүхэнд өнөөдөр · урам (data/world.json) ---------- */
  function worldLoad(){
    if(WLD.items)return Promise.resolve(WLD.items);
    if(WLD.loading)return WLD.loading;
    WLD.loading=Promise.all([fetch('data/world.json').then(function(r){return r.ok?r.json():{items:[]}}),fetch('data/world-dict.json').then(function(r){return r.ok?r.json():{}}).catch(function(){return {}}),fetch('data/news.json').then(function(r){return r.ok?r.json():{items:[]}}).catch(function(){return {items:[]}})]).then(function(a){WDICT=a[1]||{};WLD.news=(a[2]&&a[2].items)||[];WLD.items=(a[0].items||[]).concat(WLD.news);return WLD.items}).catch(function(){WLD.loading=null;return []});
    return WLD.loading;
  }
  function dayNum(){return Math.floor((Date.parse(TODAY)-Date.parse(TODAY.slice(0,4)+'-01-01'))/864e5)}
  function wById(id){return (WLD.items||[]).filter(function(x){return x.id===id})[0]}
  function worldPool(){
    var md=TODAY.slice(5),it=WLD.items||[];
    var hist=it.filter(function(x){return x.cat==='history'&&x.d===md});
    var rest=it.filter(function(x){return x.cat!=='wisdom'&&x.cat!=='history'&&!/^news/.test(x.cat)});
    var k=rest.length?dayNum()%rest.length:0;
    return hist.concat(rest.slice(k),rest.slice(0,k));
  }
  function worldFeedList(){
    var md=TODAY.slice(5),it=WLD.items||[],seed=dayNum()+1;
    function rnd(){seed=(seed*1103515245+12345)%2147483648;return seed/2147483648}
    var hist=it.filter(function(x){return x.cat==='history'&&x.d===md});
    var mid=it.filter(function(x){return x.cat!=='wisdom'&&!(x.cat==='history'&&x.d===md)});
    for(var i=mid.length-1;i>0;i--){var j=Math.floor(rnd()*(i+1)),tmp=mid[i];mid[i]=mid[j];mid[j]=tmp}
    var nws=mid.filter(function(x){return /^news/.test(x.cat)}).sort(function(p,q){return (q.ts||'')<(p.ts||'')?-1:1});mid=mid.filter(function(x){return !/^news/.test(x.cat)});
    var all=nws.concat(hist,mid,it.filter(function(x){return x.cat==='wisdom'}));
    var nw=MED.kind==='news',cc=nw?WLD.ncat:WLD.cat;
    all=all.filter(function(x){return nw===/^news/.test(x.cat)});
    return cc&&cc!=='all'?all.filter(function(x){return x.cat===cc}):all;
  }
  var NCATS=['all','newsw','newss','newst'],WCATS=['all','country','space','nature','science','history','culture','food','tech','wisdom'];
  function wCatBar(){
    var nw=MED.kind==='news',it=(WLD.items||[]).filter(function(x){return nw===/^news/.test(x.cat)}),cnt={all:it.length},cur=nw?WLD.ncat:WLD.cat;it.forEach(function(x){cnt[x.cat]=(cnt[x.cat]||0)+1});
    var ic={newsw:'📰',newss:'🔭',newst:'🤖',all:'✨',country:'🌏',space:'🪐',nature:'🌿',science:'🔬',history:'📜',culture:'🎎',food:'🍜',tech:'💡',wisdom:'💬'};
    return '<div class="wcats" id="wCats" role="group">'+(nw?NCATS:WCATS).filter(function(k){return cnt[k]}).map(function(k){
      return '<button type="button" class="chip" data-wc="'+k+'" aria-pressed="'+(cur===k)+'">'+ic[k]+' '+esc(T(k==='all'?'catAll':'cat'+k.charAt(0).toUpperCase()+k.slice(1)))+' <small>'+cnt[k]+'</small></button>';
    }).join('')+'</div>';
  }
  function worldQuote(){var q=(WLD.items||[]).filter(function(x){return x.cat==='wisdom'});return q.length?q[dayNum()%q.length]:null}
  function segW(s){
    if(!HSKD)HSKD=buildD(HSKRAW);
    var out=[],i=0,a=Array.from(String(s||''));
    while(i<a.length){
      var done=false;
      if(/[一-鿿]/.test(a[i])){
        for(var n=Math.min(6,a.length-i);n>=1;n--){
          var w=a.slice(i,i+n).join('');
          if(WDICT[w]){out.push({d:w});i+=n;done=true;break}
          if(HSKD&&HSKD[w]){out.push({h:w});i+=n;done=true;break}
        }
      }
      if(!done){out.push({t:a[i]});i++}
    }
    return out;
  }
  function zhRuby(s,hv,cls){
    return (cls==='mfw'?segW(s):segZh(s)).map(function(x){
      if(x.d)return '<button type="button" class="mfw xd" data-x="'+esc(x.d)+'" lang="zh"><ruby>'+esc(x.d)+'<rt>'+esc(WDICT[x.d][0])+'</rt></ruby></button>';
      if(!x.h){
        if(cls==='mfw'&&/[一-鿿]/.test(x.t))return '<button type="button" class="'+cls+' xc" data-x="'+esc(x.t)+'" lang="zh">'+esc(x.t)+'</button>';
        return esc(x.t);
      }
      var hit=hskLookup(x.h),nw=hv&&!hv[x.h]&&hM(x.h);
      return '<button type="button" class="'+cls+(nw?' new':'')+'" data-h="'+esc(x.h)+'" lang="zh"><ruby>'+esc(x.h)+'<rt>'+esc(hP(x.h,hit.p))+'</rt></ruby></button>';
    }).join('');
  }
  function wMeta(x){
    if(x.cat==='history')return T('wHist')+(x.y?' · '+x.y:(x.d?' · '+x.d:''));
    return T('cat'+x.cat.charAt(0).toUpperCase()+x.cat.slice(1))+(x.nd?' · '+x.nd:'');
  }
  function wTail(x){return x.mn?esc(x.mn):(x.u?'<a class="wsrc" href="'+esc(x.u)+'" target="_blank" rel="noopener">'+esc(T('wSrc'))+' ↗</a>':'')}
  function wLevel(x){var m=0;mediaWords({lines:[{zh:x.zh}]}).forEach(function(w){if(w.l>m)m=w.l});return m}
  function wKeys(x,hv){
    var ws=mediaWords({lines:[{zh:x.zh}]}).filter(function(w){return w.m});
    ws.sort(function(a,b){return (hv[a.h]?1:0)-(hv[b.h]?1:0)||a.l-b.l});
    ws=ws.slice(0,3);if(!ws.length)return '';
    return '<div class="wkeys"><span class="wkl">🔑 '+esc(T('wKeys'))+'</span>'+ws.map(function(w){return '<button type="button" class="mfw wkw'+(hv[w.h]?' have':'')+'" data-h="'+esc(w.h)+'"><b lang="zh">'+esc(w.h)+'</b><i>'+esc(w.p)+'</i><small>= '+esc(String(w.m).split(/[,;，；(（]/)[0].trim().slice(0,22))+'</small></button>'}).join('')+'</div>';
  }
  function wNewWords(x){var hv=haveSet();return mediaWords({lines:[{zh:x.zh}]}).filter(function(w){return !hv[w.h]&&w.m})}
  function worldCardRender(){
    var c=$('worldCard'),q=$('quote');if(!c)return;
    worldLoad().then(function(items){
      if(!items.length){c.hidden=true;if(q)q.hidden=true;return}
      var pool=worldPool(),x=pool[WLD.off%pool.length],hv=haveSet(),nw=wNewWords(x).length;
      c.hidden=false;c.className='card wcard w-'+x.cat;
      c.innerHTML='<div class="between"><span class="wbadge">'+x.e+' '+esc(wMeta(x))+'</span><span class="hint">'+esc(T('wHome'))+'</span></div>'+
        '<h3 class="wt">'+esc(x.t)+'</h3><div class="wzh" lang="zh">'+zhRuby(x.zh,hv,'wfw')+'</div><div class="wmn">'+wTail(x)+'</div>'+
        '<div class="row"><button class="btn small" type="button" data-wsay="'+x.id+'" aria-label="sound">🔊</button>'+(nw?'<button class="btn small ghost" type="button" data-wadd="'+x.id+'">'+esc(T('wAdd',{n:nw}))+'</button>':'')+
        '<button class="btn small ghost" type="button" data-wnext>'+esc(T('wNext'))+'</button><button class="btn small ghost" type="button" data-wopen>'+esc(T('wOpen'))+'</button></div>';
      var qt=worldQuote();
      if(q){
        if(qt){q.hidden=false;q.innerHTML='<span class="qlbl">💡 '+esc(T('wQuote'))+'</span><button type="button" class="qzh" data-wsay="'+qt.id+'" lang="zh">'+esc(qt.zh)+'</button><span class="qmn">'+esc(qt.mn)+'</span>'}
        else q.hidden=true;
      }
    });
  }
  function renderWorldFeed(){
    mediaStop();
    var box=$('mBody');
    worldLoad().then(function(){
      if((MED.kind!=='world'&&MED.kind!=='news')||MED.cur)return;
      var L=worldFeedList();
      if(!L.length){box.innerHTML=wCatBar()+'<div class="empty">'+T('mEmpty')+'</div>';return}
      var hv=haveSet();
      box.innerHTML=wCatBar()+'<div class="mfeed wfeed pin" id="wFeed">'+L.map(function(x,i){
        var nw=wNewWords(x).length;
        return '<section class="mslide wslide w-'+x.cat+'" data-wi="'+x.id+'"><div class="wtop"><span class="wbadge">'+x.e+' '+esc(wMeta(x))+'</span><span class="wnum">'+(i+1)+' / '+L.length+'</span></div>'+
          '<div class="wmid"><div class="wemo">'+x.e+'</div><h3 class="wtt" data-wsay="'+x.id+'">'+esc(x.t)+(wLevel(x)?' <span class="badge">HSK '+wLevel(x)+'</span>':'')+'</h3><div class="wzh" lang="zh">'+zhRuby(x.zh,hv,'mfw')+'</div><div class="wmn" data-wsay="'+x.id+'">'+wTail(x)+'</div>'+wKeys(x,hv)+'</div>'+
          '<div class="mfside"><button type="button" data-wsay="'+x.id+'" aria-label="sound">🔊</button><button type="button" data-wpy aria-label="pinyin">拼</button><button type="button" data-wwords="'+x.id+'">📚<small>'+nw+'</small></button></div>'+
          (i===0?'<div class="wswipe">'+esc(T('wGuide'))+'<br>'+esc(T('wSwipe'))+'</div>':'')+'</section>';
      }).join('')+'</div><div class="card mfcard" id="wfCard" hidden></div>';
    });
  }
  function wCharCard(ch){
    var c=$('wfCard');if(!c)return;c.hidden=false;
    var d=WDICT[ch];
    if(d){c.innerHTML='<div class="between"><span class="h big" lang="zh">'+esc(ch)+'</span><span class="badge">'+esc(T('wOutShort'))+'</span></div><div class="p">'+esc(d[0])+'</div><div class="m"><b>'+esc(d[1])+'</b></div>'+(d[2]?'<div class="hint">'+esc(d[2])+'</div>':'')+'<div class="row"><button class="btn ghost small" type="button" data-msp="'+esc(ch)+'">🔊</button></div>';return}
    c.innerHTML='<div class="between"><span class="h big" lang="zh">'+esc(ch)+'</span></div><div class="hint">'+esc(T('wOutHsk'))+'</div><div class="row"><button class="btn ghost small" type="button" data-msp="'+esc(ch)+'">🔊</button></div>';
  }
  function wWordCard(h){
    var hit=hskLookup(h),m=hM(h),has=haveSet()[h],c=$('wfCard');if(!c||!hit)return;
    c.hidden=false;
    c.innerHTML='<div class="between"><span class="h big" lang="zh">'+esc(h)+'</span><span class="badge">HSK '+hit.l+'</span></div><div class="p">'+esc(hP(h,hit.p))+'</div><div class="m">'+esc(m||'—')+'</div>'+
      '<div class="row"><button class="btn ghost small" type="button" data-msp="'+esc(h)+'">🔊</button>'+(has?'<span class="hint">'+esc(T('mHave'))+'</span>':(m?'<button class="btn small" type="button" data-wfa="'+esc(h)+'">+ '+esc(T('mAddOne'))+'</button>':''))+'<button class="btn small ghost" type="button" data-wfx>×</button></div>';
  }
  document.addEventListener('click',function(e){
    var t=e.target;if(!t.closest)return;
    var b;
    if((b=t.closest('[data-wc]'))){if(MED.kind==='news')WLD.ncat=b.dataset.wc;else WLD.cat=b.dataset.wc;renderWorldFeed();return}
    if((b=t.closest('[data-wsay]'))){var x=wById(b.dataset.wsay);x&&speak(x.zh);return}
    if(t.closest('[data-wnext]')){WLD.off++;worldCardRender();return}
    if(t.closest('[data-txgo]')){var ti=$('txIn');if(ti)txSet(ti.value);
      if(!isPrem()){var u=txUse();if(u>=TXF.n){var o=$('txOut');if(o)o.innerHTML='<div class="card prlock"><p>'+esc(T('prTxDone',{n:TXF.n}))+'</p><button class="btn" type="button" data-prgo="1">'+esc(T('prOpen'))+'</button></div>';return}txUse(1)}
      renderTextOut();return}
    if(t.closest('[data-txclr]')){txSet('');var tc=$('txIn');if(tc){tc.value='';tc.focus()}renderTextOut();return}
    if(t.closest('[data-txadd]')){
      var hv3=haveSet(),n4=0;
      var lim=isPrem()?1e9:10,nwl=mediaWords({lines:[{zh:txGet()}]}).filter(function(w){return !hv3[w.h]&&w.m});
      nwl.forEach(function(w){if(n4<lim&&mediaAdd(w.h))n4++});if(nwl.length>lim&&n4>=lim)toast(T('prAddLim',{n:lim}),'think');
      if(n4){syncSummary(TODAY);toast(T('tAddedN',{n:n4}),'cheer');renderAll();renderTextOut()}return}
    if(t.closest('[data-wopen]')){MED.kind='world';MED.userK=1;MED.cur=null;showTab('media');return}
    if((b=t.closest('[data-wadd]'))){
      var x2=wById(b.dataset.wadd),n=0;
      x2&&wNewWords(x2).forEach(function(w){if(mediaAdd(w.h))n++});
      if(n){syncSummary(TODAY);toast(T('tAddedN',{n:n}),'cheer');renderAll()}return}
    if(t.closest('#worldCard')&&(b=t.closest('.wfw'))){
      var h=b.dataset.h,hit=hskLookup(h);speak(h);toast(h+' · '+hP(h,hit&&hit.p)+' — '+(hM(h)||''),'think');return}
    if(!t.closest('#wFeed')&&!t.closest('#wfCard')&&!t.closest('#txOut'))return;
    if(t.closest('[data-wpy]')){var f=$('wFeed');f.classList.toggle('pin');return}
    if((b=t.closest('[data-wwords]'))){
      var x3=wById(b.dataset.wwords),n3=0;
      x3&&wNewWords(x3).forEach(function(w){if(mediaAdd(w.h))n3++});
      if(n3){syncSummary(TODAY);toast(T('tAddedN',{n:n3}),'cheer');renderAll();var sl=b.closest('.wslide');sl.querySelectorAll('.mfw.new').forEach(function(z){z.classList.remove('new')});b.querySelector('small').textContent='0'}
      else toast(T('mAllKnown'));
      return}
    if((b=t.closest('.mfw'))){if(b.dataset.x){wCharCard(b.dataset.x);return}wWordCard(b.dataset.h);return}
    if((b=t.closest('[data-wfa]'))){if(mediaAdd(b.dataset.wfa)){syncSummary(TODAY);toast(T('tAdded'),'cheer');renderAll();wWordCard(b.dataset.wfa)}return}
    if(t.closest('[data-wfx]')){$('wfCard').hidden=true}
  });
  function feedItems(items){var L=items.filter(function(x){return x.srcType==='file'&&/\.(mp4|webm)$/i.test(x.src||'')});return L.filter(function(x){return x.story}).reverse().concat(L.filter(function(x){return !x.story}))}
  function mediaStop(){document.querySelectorAll('#mBody video,#mBody audio').forEach(function(v){try{v.pause()}catch(e){}});if(MED&&MED.obs){MED.obs.disconnect();MED.obs=null}}
  function isAud(x){return /\.(mp3|m4a|wav|ogg)$/i.test(x.src||'')}
  function lineEnd(L,i){var l=L[i];return l.e!=null?l.e:(L[i+1]&&L[i+1].t!=null?L[i+1].t:l.t+4)}
  function capHtml(ln){
    var hv=haveSet();
    var z=segZh(ln.zh).map(function(x){
      if(!x.h)return esc(x.t);
      var hit=hskLookup(x.h),nw=!hv[x.h]&&hM(x.h);
      return '<button type="button" class="mfw'+(nw?' new':'')+'" data-h="'+esc(x.h)+'" lang="zh"><ruby>'+esc(x.h)+'<rt>'+esc(hP(x.h,hit.p))+'</rt></ruby></button>';
    }).join('');
    return '<div class="mfz">'+z+'</div>'+(ln.mn?'<div class="mfm">'+esc(ln.mn)+'</div>':'');
  }
  function fmtT(x){x=+x;if(!isFinite(x)||x<0)x=0;return Math.floor(x/60)+':'+('0'+Math.floor(x%60)).slice(-2)}
  function hueOf(str){var h=0;String(str||'').split('').forEach(function(c){h=(h*31+c.charCodeAt(0))%360});return h}
  function feedCap(slide,it){
    var v=slide.querySelector('video,audio'),ct=v.currentTime,L=it.lines||[],cur=-1;
    L.forEach(function(l,i){if(l.t==null)return;if(l.t<=ct&&ct<lineEnd(L,i))cur=i});
    /* 🔁 нэг мөрийг давтаж сонсох */
    if(MED.loop){
      if(slide._lp==null&&cur>=0)slide._lp=cur;
      var lp=slide._lp;
      if(lp!=null&&L[lp]&&L[lp].t!=null&&cur!==lp&&ct>=lineEnd(L,lp)-.25){v.currentTime=L[lp].t;cur=lp}
    }else slide._lp=null;
    if(slide._cur!==cur){slide._cur=cur;slide.querySelector('.mfcap').innerHTML=cur<0?'':capHtml(L[cur])}
    var b=slide.querySelector('.mfbar i');if(b&&v.duration)b.style.width=(100*ct/v.duration)+'%';
    var t0=slide.querySelector('.mft0');if(t0){t0.textContent=fmtT(ct);slide.querySelector('.mft1').textContent=fmtT(v.duration)}
  }
  function renderMediaFeed(items){
    mediaStop();
    var L=feedItems(items),box=$('mBody');
    if(!L.length){box.innerHTML='<div class="empty">'+T('mFeedEmpty')+'</div>';return}
    var hv=haveSet();
    box.innerHTML='<div class="mfeed'+(MED.pin?' pin':'')+'" id="mFeed">'+L.map(function(x,i){
      var nw=mediaWords(x).filter(function(w){return !hv[w.h]&&w.m}).length;
      var au=isAud(x),pre=(i<2?'auto':'metadata'),src=esc(encodeURI(x.src));
      return '<section class="mslide'+(au?' aud':'')+'" data-fi="'+i+'"'+(au?' style="--h:'+hueOf(x.title||x.id)+'"':'')+'>'+(au?'<audio class="mfa" loop preload="'+pre+'" src="'+src+'"></audio><div class="mfcov"><div class="mfdisc"><span>🎵</span></div><div class="mfct">'+esc(x.title)+'</div>'+(x.titleZh?'<div class="mfcz" lang="zh">'+esc(x.titleZh)+'</div>':'')+(x.level?'<span class="badge">HSK '+x.level+'</span>':'')+'<div class="mfeq"><i></i><i></i><i></i><i></i><i></i><i></i><i></i></div><div class="mftime"><span class="mft0">0:00</span><span class="mft1">0:00</span></div><div class="mfplay" aria-hidden="true">▶</div></div>':'<video class="mfv" playsinline loop preload="'+pre+'" src="'+src+'"></video>')+'<div class="mfcap"></div>'+
        (x.story||au?'':'<div class="mftop"><b>'+esc(x.title)+'</b>'+(x.level?'<span class="badge">HSK '+x.level+'</span>':'')+'</div>')+
        '<div class="mfside"><button type="button" data-mfsnd aria-label="sound">'+(MED.muted?'🔇':'🔊')+'</button><button type="button" data-mfpy aria-label="pinyin">拼</button><button type="button" data-mfloop aria-label="repeat line" class="'+(MED.loop?'on':'')+'">🔁</button><button type="button" data-mfspd aria-label="speed">'+(MED.spd||1)+'×</button><button type="button" data-mfwords>📚<small>'+nw+'</small></button></div><div class="mfbar"><i></i></div></section>';
    }).join('')+'</div><div class="card mfcard" id="mfCard" hidden></div>';
    var feed=$('mFeed');
    MED.obs=new IntersectionObserver(function(es){es.forEach(function(en){
      var v=en.target.querySelector('video,audio');
      if(en.isIntersecting&&en.intersectionRatio>=.6){v.muted=MED.muted;v.playbackRate=MED.spd||1;v.play().catch(function(){});$('mfCard').hidden=true}
      else{v.pause()}
    })},{root:feed,threshold:[.6]});
    feed.querySelectorAll('.mslide').forEach(function(sl,i){
      var v=sl.querySelector('video,audio');v.muted=MED.muted;
      v.addEventListener('timeupdate',function(){feedCap(sl,L[i])});v.addEventListener('loadedmetadata',function(){feedCap(sl,L[i])});
      v.addEventListener('play',function(){sl.classList.add('playing')});v.addEventListener('pause',function(){sl.classList.remove('playing')});
      MED.obs.observe(sl);
    });
    MED.feed=L;
  }
  function feedWordsSheet(it){
    var hv=haveSet(),nw=mediaWords(it).filter(function(w){return !hv[w.h]&&w.m}),c=$('mfCard');
    c.hidden=false;c.dataset.it=it.id;
    c.innerHTML='<div class="between"><h3>'+esc(T('mNew',{n:nw.length}))+'</h3><button class="btn small ghost" type="button" data-mfx>×</button></div>'+
      (nw.length?'<div class="list">'+nw.map(function(w){return '<div class="w mrow"><span class="h" lang="zh">'+esc(w.h)+'</span><span><span class="p">'+esc(w.p)+'</span><br><span class="m">'+esc(w.m)+'</span></span><span class="badge">HSK '+w.l+'</span><button class="btn small ghost" type="button" data-mfa="'+esc(w.h)+'">+</button></div>'}).join('')+'</div><button class="btn" type="button" data-mfall>'+esc(T('mAddAll'))+'</button>':'<div class="empty">'+T('mAllKnown')+'</div>');
  }
  function feedWordCard(h,slide){
    var hit=hskLookup(h),m=hM(h),has=haveSet()[h],c=$('mfCard');
    var v=slide.querySelector('video,audio');v.pause();
    c.hidden=false;c.dataset.it='';
    c.innerHTML='<div class="between"><span class="h big" lang="zh">'+esc(h)+'</span><span class="badge">HSK '+hit.l+'</span></div><div class="p">'+esc(hP(h,hit.p))+'</div><div class="m">'+esc(m||'—')+'</div>'+
      '<div class="row"><button class="btn ghost small" type="button" data-msp="'+esc(h)+'">🔊</button>'+(has?'<span class="hint">'+esc(T('mHave'))+'</span>':(m?'<button class="btn small" type="button" data-mfa="'+esc(h)+'">+ '+esc(T('mAddOne'))+'</button>':''))+'<button class="btn small ghost" type="button" data-mfx>▶</button></div>';
  }
  document.addEventListener('click',function(e){
    var t=e.target;if(!t.closest||!t.closest('#p-media')||!$('mFeed'))return;
    var sl=t.closest('.mslide'),b;
    var it=sl&&MED.feed[+sl.dataset.fi];
    if(t.closest('[data-mfsnd]')){MED.muted=!MED.muted;document.querySelectorAll('#mFeed video,#mFeed audio').forEach(function(v){v.muted=MED.muted});document.querySelectorAll('[data-mfsnd]').forEach(function(x){x.textContent=MED.muted?'🔇':'🔊'});return}
    if(t.closest('[data-mfloop]')){MED.loop=!MED.loop;document.querySelectorAll('#mFeed .mslide').forEach(function(s){s._lp=null});document.querySelectorAll('[data-mfloop]').forEach(function(x){x.classList.toggle('on',MED.loop)});toast(MED.loop?'🔁 ON':'🔁 OFF');return}
    if(t.closest('[data-mfspd]')){MED.spd=MED.spd===1||!MED.spd?.75:(MED.spd===.75?.5:1);document.querySelectorAll('#mFeed video,#mFeed audio').forEach(function(v){v.playbackRate=MED.spd});document.querySelectorAll('[data-mfspd]').forEach(function(x){x.textContent=MED.spd+'×'});return}
    if(t.closest('[data-mfpy]')){MED.pin=!MED.pin;$('mFeed').classList.toggle('pin',MED.pin);return}
    if(t.closest('[data-mfwords]')){sl.querySelector('video,audio').pause();feedWordsSheet(it);return}
    if((b=t.closest('.mfw'))){feedWordCard(b.dataset.h,sl);return}
    if(t.closest('[data-mfx]')){$('mfCard').hidden=true;var a=document.querySelector('.mslide video:not([paused])');document.querySelectorAll('#mFeed .mslide').forEach(function(s){var r=s.getBoundingClientRect(),f=$('mFeed').getBoundingClientRect();if(r.top>=f.top-10&&r.top<f.top+f.height/2)s.querySelector('video,audio').play().catch(function(){})});return}
    if((b=t.closest('[data-mfa]'))){
      if(mediaAdd(b.dataset.mfa)){syncSummary(TODAY);toast(T('tAdded'),'cheer');var cid=$('mfCard').dataset.it,fy=$('mFeed').scrollTop;renderAll();if(cid){var x2=MED.feed.filter(function(z){return z.id===cid})[0];x2&&feedWordsSheet(x2)}else $('mfCard').hidden=true}
      return}
    if(t.closest('[data-mfall]')){
      var it2=MED.feed.filter(function(z){return z.id===$('mfCard').dataset.it})[0],n=0;
      it2&&mediaWords(it2).forEach(function(w){if(mediaAdd(w.h))n++});
      if(n){syncSummary(TODAY);toast(T('tAddedN',{n:n}),'cheer');renderAll();feedWordsSheet(it2)}return}
    if(sl&&(b=t.closest('.mfbar'))){var av=sl.querySelector('video,audio'),rc=b.getBoundingClientRect();if(av.duration)av.currentTime=Math.max(0,Math.min(1,(e.clientX-rc.left)/rc.width))*av.duration;return}
    if(sl&&t.closest('.mfv,.mfcov')){var v=sl.querySelector('video,audio');v.paused?v.play().catch(function(){}):v.pause()}
  });
  function parseLines(txt){
    return String(txt||'').split('\n').map(function(r){return r.trim()}).filter(Boolean).map(function(r){
      var t=null,m=/^(\d+):(\d{2})\s+/.exec(r);if(m){t=+m[1]*60+ +m[2];r=r.slice(m[0].length)}
      var p=r.split(/\s*\|\s*/);return {t:t,zh:p[0],mn:p[1]||''};
    }).filter(function(l){return l.zh}).map(function(l){if(l.t==null)delete l.t;return l});
  }
  function renderMediaAdmin(){
    var box=$('mAdmin');if(!box||!isOwner)return;
    mediaLoad(true).then(function(items){
      var mine=items.filter(function(x){return !x.local});
      $('mAdList').innerHTML=mine.length?mine.map(function(x){return '<div class="between"><span>'+esc(x.title)+' <small>('+esc(x.kind)+')</small></span><button class="btn small ghost" type="button" data-mdel="'+esc(x.id)+'">×</button></div>'}).join(''):'<div class="hint">'+esc(T('mEmpty'))+'</div>';
    });
  }
  $('mSave').addEventListener('click',async function(){
    if(!sb||!isOwner)return;
    var title=$('mTitle').value.trim(),lines=parseLines($('mText').value),src=$('mSrc').value.trim();
    if(!title||!lines.length){toast(T('mNeed'),'oops');return}
    var type=ytId(src)?'youtube':(/^media\/[^\/\\<>"'?#]+\.(mp4|mp3|m4a|wav|ogg|webm)$/i.test(src)?'file':'none');
    var row={id:'m_'+Date.now().toString(36),kind:$('mKind').value,level:+$('mLvl').value||null,title:title,title_zh:$('mTitleZh').value.trim(),src_type:type,src:type==='youtube'?ytId(src):(type==='file'?src:''),lines:lines};
    var x=await sb.from('media').insert(row);
    if(x.error){toast(String(x.error.message||x.error));return}
    ['mTitle','mTitleZh','mSrc','mText'].forEach(function(i){$(i).value=''});
    toast(T('mSaved'),'cheer');MED.items=null;renderMediaAdmin();
  });
  document.addEventListener('click',async function(e){
    var t=e.target;if(!t.closest)return;
    var d=t.closest('[data-mdel]');if(d&&isOwner&&sb){var x=await sb.from('media').delete().eq('id',d.dataset.mdel);if(!x.error){MED.items=null;renderMediaAdmin()}return}
    if(!t.closest('#p-media'))return;
    var b;
    if((b=t.closest('[data-mk]'))){MED.kind=b.dataset.mk;MED.userK=1;renderMedia();return}
    if((b=t.closest('[data-mi]'))){MED.cur=b.dataset.mi;window.scrollTo(0,0);renderMedia();return}
    if(t.closest('#mBack')){MED.cur=null;MED.quiz=null;renderMedia();return}
    if((b=t.closest('.mw'))){mediaWordCard(b.dataset.h);return}
    if((b=t.closest('[data-msp]'))){speak(b.dataset.msp);return}
    if((b=t.closest('[data-ma]'))){
      if(mediaAdd(b.dataset.ma)){syncSummary(TODAY);toast(T('tAdded'),'cheer');var y=window.scrollY;renderAll();renderMedia();setTimeout(function(){window.scrollTo(0,y)},60)}
      return}
    if(t.closest('#mAddAll')){
      var it=MED.items.filter(function(x){return x.id===MED.cur})[0],n=0;
      mediaWords(it).forEach(function(w){if(mediaAdd(w.h))n++});
      if(n){syncSummary(TODAY);toast(T('tAddedN',{n:n}),'cheer');renderAll();renderMedia()}return}
    if(t.closest('#mQuizBtn')||t.closest('#mQuizBtn2')){mediaQuiz(MED.items.filter(function(x){return x.id===MED.cur})[0]);return}
    if((b=t.closest('[data-mo]'))&&MED.quiz){
      var Q=MED.quiz,x2=Q.q[Q.i];if(b.dataset.mo===x2.w.m)Q.ok++;else toast(x2.w.h+' = '+x2.w.m,'think');
      Q.i++;renderMediaQuiz()}
  });

  /* ---------- server mode (Supabase) ---------- */
  async function fetchAll(mk){var out=[],i=0,n=0;for(;;){var x=await mk().range(i,i+999);if(x.error)throw x.error;var d=x.data||[];out=out.concat(d);if(!d.length||++n>300)break;i+=d.length}return out}
  /* Бүх хүсэлтийг ЗЭРЭГ илгээнэ (өмнө нь ~14 дараалсан хүсэлт байсан → удаан) */
  async function refreshLoad(){
    if(!sb||!uid)return null;
    try{
      return await Promise.all([
        fetchAll(function(){return sb.from('profiles').select('*').order('id')}),
        sb.from('hsk_edits').select('*'),
        sb.from('gram_edits').select('*'),
        sb.from('classes').select('*'),
        sb.from('class_members').select('*'),
        sb.from('tasks').select('*').order('created_at'),
        sb.from('task_done').select('*'),
        sb.from('site').select('notice').eq('id','cfg').maybeSingle()
      ]);
    }catch(e){return null}
  }
  function refreshApply(r){
    if(!r)return;
    var rows=r[0],he=r[1],ge=r[2],c1=r[3],c2=r[4],c3=r[5],c4=r[6],s=r[7];
    if(!he.error){HSKED={};(he.data||[]).forEach(function(x){HSKED[x.h]={p:x.p,m:x.m}})}
    if(!ge.error){GRAMED={};(ge.data||[]).forEach(function(x){GRAMED[x.k]={l:x.l,m:x.m,z:x.z,t:x.t,deleted:!!x.deleted}})}
    if(!c1.error&&!c3.error)CL={classes:c1.data||[],members:c2.data||[],tasks:c3.data||[],done:c4.data||[]};
    P={};CFG.hidden={};
    rows.forEach(function(x){P[x.id]=Object.assign({},x.data||{},{nick:x.nick});if(x.hidden)CFG.hidden[x.id]=1});
    CFG.notice=(s.data&&s.data.notice)||'';
  }
  async function refresh(){
    var r=await refreshLoad();if(!r)return;
    try{refreshApply(r);renderAll()}catch(e){}
  }
  /* ---- сүүлийн мэдээллийн хуулбар: дараагийн нээлт хүлээлгүй шууд гарна ---- */
  var SNAPK='hsk-snap-';
  function saveSnap(){
    if(mode!=='db'||!uid)return;
    try{localStorage.setItem(SNAPK+uid,JSON.stringify({v:1,S:S,owner:isOwner,P:P,CL:CL,CFG:CFG,HSKED:HSKED,GRAMED:GRAMED,login:loginName}))}catch(e){}
  }
  function readSnap(id){try{var j=JSON.parse(lget(SNAPK+id)||'null');return j&&j.v===1&&j.S?j:null}catch(e){return null}}
  function applySnap(user,j){
    uid=user.id;loginName=j.login||(user.email||'').split('@')[0];showEmail(user.email);mode='db';needAuth=false;
    S=j.S;isOwner=!!j.owner;
    if(j.P)P=j.P;if(j.CL)CL=j.CL;if(j.CFG)CFG=j.CFG;if(j.HSKED)HSKED=j.HSKED;if(j.GRAMED)GRAMED=j.GRAMED;
  }
  function peekUser(){
    try{var k='sb-'+SBCFG.url.split('//')[1].split('.')[0]+'-auth-token',j=JSON.parse(lget(k)||'null');
      return (j&&j.user&&j.user.id)?j.user:((j&&j.currentSession&&j.currentSession.user)||null)}catch(e){return null}
  }
  document.addEventListener('visibilitychange',function(){if(document.visibilityState==='hidden')saveSnap()});
  window.addEventListener('pagehide',saveSnap);

  /* ---------- Offline: интернэтгүй үед хийсэн өөрчлөлтийг сервер рүү буцааж илгээх ---------- */
  async function pushLocal(){
    if(!sb||!uid||mode!=='db'||lget('hsk-unsynced-'+uid)!=='1')return false;
    try{
      var r={id:uid,nick:S.profile.nick,data:Object.assign({},S.profile,{chk:S.chk,act:S.act}),updated_at:new Date().toISOString()};
      var x=await sb.from('profiles').upsert(r);if(x.error)throw x.error;
      var all=wordsArr().map(wRow);
      for(var k=0;k<all.length;k+=200){x=await sb.from('words').upsert(all.slice(k,k+200));if(x.error)throw x.error}
      lset('hsk-unsynced-'+uid,'0');return true;
    }catch(e){return false}
  }
  window.addEventListener('offline',function(){toast(T('netOff'),'sleep')});
  window.addEventListener('online',function(){pushLocal().then(function(ok){if(ok)toast(T('netOn'),'cheer')})});
  async function startSession(user,bg){
    uid=user.id;loginName=(user.email||'').split('@')[0];showEmail(user.email);mode='db';needAuth=false;
    var res=await Promise.all([
      sb.from('profiles').select('*').eq('id',uid).maybeSingle(),
      fetchAll(function(){return sb.from('words').select('*').eq('uid',uid).order('id')}),
      sb.from('admins').select('uid').eq('uid',uid).maybeSingle(),
      refreshLoad()
    ]);
    var pr=res[0],ws=res[1],a=res[2];
    if(pr.error)throw pr.error;
    if(pr.data){
      var d=Object.assign({},pr.data.data||{});
      S={profile:d,words:{},chk:d.chk||{},act:d.act||{}};delete d.chk;delete d.act;d.nick=pr.data.nick||d.nick;
      ws.forEach(function(w){S.words[w.id]={id:w.id,l:w.l,h:w.h,p:w.p||'',m:w.m,e:w.e||'',d:w.d,box:w.box||0,due:w.due}});
    }else if(S.profile.nick){
      createProfile();
      var all=wordsArr().map(wRow);
      for(var k=0;k<all.length;k+=200){(function(ch){q(async function(){var x=await sb.from('words').upsert(ch);if(x.error)throw x.error})})(all.slice(k,k+200))}
      lset('hsk-v3','');
    }else{S={profile:{},words:{},chk:{},act:{}}}
    isOwner=!!a.data;
    await premLoad();
    try{refreshApply(res[3])}catch(e){}
    renderTasks();renderAll();
    if(!bg){startDeck();showTab('today')}
    saveSnap();
  }
  function emailOf(l){return l.toLowerCase()+'@hskapp.mn'}
  function showEmail(e){var el=$('acCur');if(!el)return;var fake=!e||/@hskapp\.mn$/i.test(e);el.textContent=fake?T('accNone',{n:(e||'').split('@')[0]}):T('accCur',{e:e});el.style.color=fake?'var(--bad)':''}
  function speak(t,cb){
    if(!window.speechSynthesis){toast(T('speakErr'),'oops');return}
    var vs=speechSynthesis.getVoices(),v=vs.filter(function(x){return /^zh/i.test(x.lang)})[0];
    if(vs.length&&!v){toast(T('speakErr'),'oops');return}
    var u=new SpeechSynthesisUtterance(t);u.lang='zh-CN';u.rate=spRate();if(v)u.voice=v;
    if(cb){u.onend=cb;u.onerror=cb}
    speechSynthesis.cancel();speechSynthesis.speak(u);
  }
  function spRate(){return lget('hsk-rate')==='slow'?.55:.85}
  function slowSync(){var on=lget('hsk-rate')==='slow';document.querySelectorAll('[data-slow]').forEach(function(b){b.setAttribute('aria-pressed',on?'true':'false')})}
  var PQ=null;
  function pqStop(){PQ=null;try{speechSynthesis.cancel()}catch(e){}document.querySelectorAll('[data-playq]').forEach(function(b){b.textContent=T('lsPlay')})}
  function pqPlay(sel,btn){
    if(PQ){pqStop();return}
    var list=Array.prototype.slice.call(document.querySelectorAll(sel+' [data-speak]')).slice(0,25).map(function(b){return b.dataset.speak});
    if(!list.length)return;
    var my=PQ={i:0};btn.textContent=T('lsStop');
    (function step(){if(PQ!==my)return;if(my.i>=list.length){pqStop();return}
      speak(list[my.i++],function(){setTimeout(step,700)})})();
  }
  document.addEventListener('click',function(e){
    var b=e.target.closest('[data-slow]');if(b){lset('hsk-rate',lget('hsk-rate')==='slow'?'normal':'slow');slowSync();return}
    b=e.target.closest('[data-playq]');if(b)pqPlay(b.dataset.playq,b)
  });
  document.addEventListener('click',function(e){var b=e.target.closest('[data-speak]');if(b)speak(b.dataset.speak)});
  /* ---------- mistakes + favorites (saved in the profile) ---------- */
  var missDirty=false;
  function addD(n){var d=new Date();d.setDate(d.getDate()+n);return iso(d)}
  function missDue(){var m=(S.profile&&S.profile.miss)||{};return Object.keys(m).filter(function(h){return !m[h].nx||m[h].nx<=TODAY})}
  function missMap(){if(!S.profile.miss)S.profile.miss={};return S.profile.miss}
  function favMap(){if(!S.profile.fav)S.profile.fav={};return S.profile.fav}
  function isFav(h){return !!(S.profile.fav&&S.profile.fav[h])}
  function missAdd(w){
    if(!hasProfile()||!w||!w.h)return;var m=missMap(),o=m[w.h]||{n:0};
    m[w.h]={p:w.p||o.p||'',m:w.m||o.m||'',n:(o.n||0)+1,ok:0,t:TODAY,nx:addD(1)};missDirty=true;
    var ks=Object.keys(m);if(ks.length>300){ks.sort(function(a,b){return String(m[a].t).localeCompare(String(m[b].t))});delete m[ks[0]]}
  }
  function missOk(h){
    if(!hasProfile()||!S.profile.miss||!S.profile.miss[h])return;var o=S.profile.miss[h];o.ok=(o.ok||0)+1;
    if(o.ok>=2)delete S.profile.miss[h];else o.nx=addD(3);missDirty=true;
  }
  function missFlush(){if(missDirty){missDirty=false;pPatch({miss:S.profile.miss||{},fav:S.profile.fav||{},srs:S.profile.srs||{}})}}
  function favToggle(h){
    if(!hasProfile()){toast(T('lsNeedProfile'),'think');return}
    var f=favMap();if(f[h])delete f[h];else{var hit=hskLookup(h);f[h]={p:hP(h,hit&&hit.p),m:hM(h),t:TODAY}}
    pPatch({fav:f});renderHsk();renderLs();
  }
  var lsTab='miss';
  function renderLs(){
    if(!$('lsList'))return;
    var ms=missMap(),fs=favMap(),mk=Object.keys(ms),fk=Object.keys(fs);
    $('lsTabs').innerHTML='<button class="chip" type="button" data-lst="miss" aria-pressed="'+(lsTab==='miss')+'">'+esc(T('lsMiss'))+'<small>'+mk.length+'</small></button><button class="chip" type="button" data-lst="fav" aria-pressed="'+(lsTab==='fav')+'">'+esc(T('lsFav'))+'<small>'+fk.length+'</small></button>';
    var ks=lsTab==='miss'?mk:fk,mp=lsTab==='miss'?ms:fs;
    ks.sort(function(a,b){if(lsTab==='miss'&&(mp[b].n||0)!==(mp[a].n||0))return(mp[b].n||0)-(mp[a].n||0);return String(mp[b].t).localeCompare(String(mp[a].t))});
    $('lsList').innerHTML=ks.map(function(h){var x=mp[h],m=hM(h)||x.m;
      return '<div class="w wc'+(x.l?' lv'+x.l:'')+'"><span class="h" lang="zh">'+esc(h)+'</span><span><span class="p">'+tonePy(x.p||'')+'</span>'+(lsTab==='miss'&&x.n>1?' <span class="badge">'+(x.n>=4?'🔥 ':'')+'×'+x.n+'</span>':'')+'<br><span class="m">'+esc(m)+'</span>'+partsHint(h)+'</span><span class="wca">'+
        '<button class="btn small ghost" type="button" data-speak="'+esc(h)+'" aria-label="Audio">🔊</button> '+
        (lsTab==='fav'?'<button class="btn small ghost star" type="button" data-fav="'+esc(h)+'" aria-label="Favorite">★</button>':'<button class="btn small ghost" type="button" data-missdel="'+esc(h)+'" aria-label="Remove">✕</button>')+'</span></div>'
    }).join('')||'<div class="empty">'+esc(T(lsTab==='miss'?'lsEmptyMiss':'lsEmptyFav'))+'</div>';
    $('lsPractice').hidden=!ks.length;
    slowSync();
  }
  document.addEventListener('click',function(e){
    var b=e.target.closest('[data-lst]');if(b){lsTab=b.dataset.lst;renderLs();return}
    b=e.target.closest('[data-missdel]');if(b){delete missMap()[b.dataset.missdel];missDirty=true;missFlush();renderLs();return}
    b=e.target.closest('[data-fav]');if(b){favToggle(b.dataset.fav);return}
    if(e.target.closest('#lsPractice')){
      var mp=lsTab==='miss'?missMap():favMap(),ks=Object.keys(mp);if(!ks.length)return;
      var src=ks.map(function(h){return {h:h,p:mp[h].p||'',m:hM(h)||mp[h].m||''}}).filter(function(x){return x.m});
      if(!src.length)return;showTab('play');startGame('mean',src,'list');
    }
  });
  /* ---------- games, XP, streak, word of the day ---------- */
  var GM=null,DAYL=null;
  function shuf(a){return a.slice().sort(function(){return Math.random()-.5})}
  function mn(m){return String(m).split(/[,;(]/)[0].trim()}
  function weekXp(d){var lim=iso(new Date(today.getTime()-6*864e5)),t=0;Object.keys(d||{}).forEach(function(k){if(k>=lim)t+=d[k]});return t}
  function streakNow(){var p=S.profile||{},y=iso(new Date(today.getTime()-864e5));return p.sd===TODAY||p.sd===y?(p.streak||0):0}
  /* ---------- Эффект: confetti + богино дуу (milestone үед) ---------- */
  var fxAC=null,fxRaf=0;
  function fxOn(){return lget('hsk-fx')!=='0'}
  function fxTone(notes){
    if(!fxOn())return;
    try{
      var C=window.AudioContext||window.webkitAudioContext;if(!C)return;
      fxAC=fxAC||new C();if(fxAC.state==='suspended')fxAC.resume();
      var t=fxAC.currentTime;
      notes.forEach(function(f,i){
        var o=fxAC.createOscillator(),g=fxAC.createGain(),s=t+i*.12;
        o.type='sine';o.frequency.value=f;
        g.gain.setValueAtTime(0.0001,s);g.gain.linearRampToValueAtTime(.12,s+.02);g.gain.exponentialRampToValueAtTime(.001,s+.26);
        o.connect(g);g.connect(fxAC.destination);o.start(s);o.stop(s+.3);
      });
    }catch(e){}
  }
  function fxConfetti(n){
    if(!fxOn())return;
    try{if(window.matchMedia&&matchMedia('(prefers-reduced-motion: reduce)').matches)return}catch(e){}
    var old=document.getElementById('fxCv');if(old)old.remove();cancelAnimationFrame(fxRaf);
    var cv=document.createElement('canvas'),W=cv.width=innerWidth,H=cv.height=innerHeight,cx=cv.getContext('2d');
    cv.id='fxCv';cv.setAttribute('aria-hidden','true');
    cv.style.cssText='position:fixed;inset:0;width:100%;height:100%;pointer-events:none;z-index:9999';
    document.body.appendChild(cv);
    var cols=['#C23B22','#1F3F8F','#2E7D4F','#E0A526','#8FAAF0','#E5654C'],ps=[];
    for(var i=0;i<n;i++)ps.push({x:W/2+(Math.random()-.5)*W*.3,y:H*.35,vx:(Math.random()-.5)*11,vy:-Math.random()*11-3,w:5+Math.random()*6,h:8+Math.random()*8,r:Math.random()*6.3,vr:(Math.random()-.5)*.4,c:cols[i%cols.length]});
    var t0=Date.now();
    (function step(){
      var el=Date.now()-t0;cx.clearRect(0,0,W,H);
      ps.forEach(function(q){q.vy+=.28;q.vx*=.99;q.x+=q.vx;q.y+=q.vy;q.r+=q.vr;
        cx.save();cx.globalAlpha=Math.max(0,1-el/2200);cx.translate(q.x,q.y);cx.rotate(q.r);cx.fillStyle=q.c;cx.fillRect(-q.w/2,-q.h/2,q.w,q.h);cx.restore()});
      if(el<2200)fxRaf=requestAnimationFrame(step);else cv.remove();
    })();
  }
  function fxWin(kind){
    if(kind==='big'){fxConfetti(150);fxTone([523,659,784,1047])}
    else{fxConfetti(60);fxTone([659,880])}
  }
  (function(){var b=document.getElementById('fxTog');if(!b)return;
    b.setAttribute('aria-pressed',fxOn()?'true':'false');
    b.addEventListener('click',function(){var on=!fxOn();lset('hsk-fx',on?'1':'0');b.setAttribute('aria-pressed',on?'true':'false');if(on)fxWin('small')});
  })();
  function addXp(n){
    var p=S.profile,y=iso(new Date(today.getTime()-864e5)),st=p.sd===TODAY?(p.streak||1):(p.sd===y?(p.streak||0)+1:1);
    var oldLv=Math.floor(Math.sqrt((p.xp||0)/20))+1;
    if(p.sd!==TODAY&&st>0&&st%7===0){n+=50;toast(T('streakBonus',{n:st}),'cheer');fxWin('big')}
    var xd=Object.assign({},p.xpd||{}),old=iso(new Date(today.getTime()-21*864e5));
    Object.keys(xd).forEach(function(k){if(k<old)delete xd[k]});xd[TODAY]=(xd[TODAY]||0)+n;
    var patch={xp:(p.xp||0)+n,xpd:xd,streak:st,sd:TODAY};Object.assign(p,patch);pPatch(patch);renderPlay();
    var newLv=Math.floor(Math.sqrt(patch.xp/20))+1;
    if(newLv>oldLv){fxWin('big');toast(T('lvUp',{n:newLv}),'cheer')}
  }
  function renderPlay(){
    if(!$('plLvl'))return;
    renderPlLv();
    var ok=hasProfile();$('dayCard').hidden=!ok;if(!ok)return;
    var p=S.profile||{},xp=p.xp||0,lv=Math.floor(Math.sqrt(xp/20))+1,b=20*(lv-1)*(lv-1),n=20*lv*lv;
    $('plLvl').textContent='Lv '+lv;$('plXp').textContent=xp+' / '+n+' XP';
    $('plXpBar').style.width=Math.round((xp-b)*100/(n-b))+'%';$('plStreak').textContent='🔥 '+streakNow()+' '+T('days');
    if(!DAYL){DAYL=[];LEVELS.forEach(function(l){(HR()[l]||'').split(',').forEach(function(it){var a=it.split('|');if(hM(a[0]))DAYL.push(a)})})}
    if(DAYL.length){var a=DAYL[(Math.floor(today.getTime()/864e5)*7919)%DAYL.length];
      $('dayBody').innerHTML='<div class="w" style="background:var(--surface)"><span class="h" lang="zh">'+esc(a[0])+'</span><span><span class="p">'+esc(hP(a[0],a[1]))+'</span><br><span class="m">'+esc(hM(a[0]))+'</span></span><span><button class="btn small ghost" type="button" data-speak="'+esc(a[0])+'">🔊</button> <button class="btn small ghost" type="button" data-write="'+esc(a[0])+'">✍</button></span></div>'}
  }
  function gPool(){
    var o=[];wordsArr().forEach(function(w){if(w.m)o.push({h:w.h,p:w.p,m:w.m})});var mine=o.length;
    gLevels().forEach(function(l){(HR()[l]||'').split(',').forEach(function(it){var a=it.split('|'),m=hM(a[0]);if(m)o.push({h:a[0],p:hP(a[0],a[1]),m:m,l:l})})});
    return {all:o,mine:o.slice(0,mine)};
  }
  /* тоглоомын түвшин: «Авто» = миний түвшин ба нэг түвшин доош, эсвэл гараар сонгосон HSK түвшин */
  function plLvSel(){var v=0;try{v=+lget('hsk-pl')||0}catch(e){}return v>=1&&v<=6?v:0}
  function gLevels(){var s=plLvSel();if(s)return [s];var lv=(S.profile&&S.profile.level)||2;return lv<=1?[1]:[lv-1,lv]}
  var SPT=null;
  function startGame(mode,custom,back){
    var P=gPool(),src;
    if(custom)src=shuf(custom).slice(0,10);
    else if(mode==='write'){
      var ms=hasProfile()?missMap():{},pool=(P.mine.length>=5?P.mine:P.all).filter(function(w){var n=Array.from(w.h).filter(function(c){return /[\u4e00-\u9fff]/.test(c)}).length;return n>=1&&n<=3});
      src=shuf(pool.filter(function(w){return ms[w.h]})).concat(shuf(pool.filter(function(w){return !ms[w.h]}))).slice(0,5);
    }
    else if(mode==='sprint')src=shuf(P.all).slice(0,300);
    else if(mode==='build')src=sbPool();
    else if(mode==='cloze')src=clPool();
    else if(mode==='tone')src=tnPool(P);
    else if(mode==='match'){var mw=mcPool(P);src=mw.length>=12?[mw.slice(0,6),mw.slice(6,12)]:[]}
    else src=shuf(P.mine.length>=5?P.mine:P.all).slice(0,10);
    if(!src.length){toast(T('gEmpty'),'oops');return}
    $('plWrong')&&($('plWrong').hidden=true);
    GM={mode:mode,src:src,i:0,ok:0,all:P.all,back:back||''};
    if(mode==='sprint'){GM.end=Date.now()+60000;clearInterval(SPT);SPT=setInterval(function(){if(!GM||GM.mode!=='sprint'){clearInterval(SPT);return}var l=Math.max(0,Math.ceil((GM.end-Date.now())/1000));$('plScore').textContent='⏱ '+l+' · ✓ '+GM.ok;$('plProg').style.width=Math.min(100,Math.round((60-l)*100/60))+'%';if(l<=0){clearInterval(SPT);endGame()}},250)}
    $('plMenu').hidden=true;$('plGame').hidden=false;nextQ();
  }
  function endGame(){
    if(GM.mode==='sprint'){
      clearInterval(SPT);var wr=GM.wrong,sc=GM.ok,pb=(S.profile&&S.profile.sb)||0,nb=sc>pb,xps=Math.min(sc*2,60);
      if(hasProfile()){if(nb)pPatch({sb:sc});if(S.profile)S.profile.sb=Math.max(pb,sc);addXp(xps)}
      if(nb&&sc>0)fxWin('big');$('plRes').textContent=T('sprintRes',{a:sc,b:Math.max(pb,sc),x:xps})+(nb&&sc>0?' 🏆':'');$('plGame').hidden=true;$('plMenu').hidden=false;GM=null;missFlush();showWrong(wr);return;
    }
    var xp=GM.ok*(GM.mode==='build'||GM.mode==='write'?15:10)+(GM.ok===GM.src.length?10:0);addXp(xp);if(GM.ok===GM.src.length&&GM.src.length>=3)fxWin('small');if(GM.task)taskResult(GM.task,GM.ok,GM.src.length);
    $('plRes').textContent=T('plRes',{a:GM.ok,b:GM.src.length,x:xp});$('plGame').hidden=true;$('plMenu').hidden=false;var bk=GM.back,wr2=GM.wrong;GM=null;missFlush();showWrong(wr2);if(bk){showTab(bk);toast($('plRes').textContent)}
  }
  function nextQ(){
    if(GM.i>=GM.src.length){endGame();return}
    var q=GM.src[GM.i];$('plQ').textContent=(GM.i+1)+' / '+GM.src.length;$('plScore').textContent=scoreTxt();
    if(GM.mode!=='sprint'){
      $('plProg').style.width=Math.round(GM.i*100/GM.src.length)+'%';
      var gc=$('plGame');gc.classList.remove('qin');void gc.offsetWidth;gc.classList.add('qin');
    }
    $('plOpts').className='list m-'+GM.mode;
    $('plBuilt').textContent='';$('plBuilt').style.color='';
    if(GM.mode==='build'){sbStart(q);return}
    if(GM.mode==='match'){mcStart(q);return}
    if(GM.mode==='tone'){tnStart(q);return}
    if(GM.mode==='cloze'){clStart(q);return}
    if(GM.mode==='write'){
      GM.q=q;GM.wi=0;GM.wm=0;GM.hinted=false;GM.chars=Array.from(q.h).filter(function(c){return /[\u4e00-\u9fff]/.test(c)});
      $('plPrompt').innerHTML='<div style="font-size:1.3rem;font-weight:800">'+esc(q.p||'')+'</div><div style="font-size:1rem;font-weight:500;margin-top:2px">'+esc(mn(q.m))+'</div>';
      $('plOpts').innerHTML='<div id="wBox" style="display:flex;justify-content:center;min-height:240px"></div><div class="row" style="justify-content:center"><button class="btn ghost" type="button" data-speak="'+esc(q.h)+'">🔊</button><button class="btn ghost" type="button" data-whint="1">💡</button><button class="btn ghost" type="button" data-wskip="1">'+esc(T('micSkip'))+'</button></div>';
      wrWrite();return;
    }
    if(GM.mode==='speak'){
      GM.q=q;GM.tries=0;
      $('plPrompt').innerHTML='<span lang="zh">'+esc(q.h)+'</span><div style="font-size:1rem;font-weight:600;margin-top:4px">'+esc(q.p||'')+'</div><div style="font-size:.95rem;font-weight:500;margin-top:2px">'+esc(mn(q.m))+'</div>';
      $('plBuilt').textContent=T('micTap');
      $('plOpts').innerHTML='<button class="btn" type="button" data-mic="1">🎤</button><button class="btn ghost" type="button" data-speak="'+esc(q.h)+'">🔊</button><button class="btn ghost" type="button" data-micskip="1">'+esc(T('micSkip'))+'</button>';
      return;
    }
    var opts=[q],qc=Array.from(q.h);
    function okOpt(r){return r&&!opts.some(function(o){return o.h===r.h||mn(o.m)===mn(r.m)})}
    /* төстэй сатаарлуулагч: ижил урттай эсвэл ижил иероглифтэй үгээс 2-г нь, үлдсэнийг санамсаргүй */
    for(var tr=0;opts.length<3&&tr<400;tr++){var r0=GM.all[Math.floor(Math.random()*GM.all.length)];
      if(okOpt(r0)&&(r0.h.length===q.h.length||qc.some(function(c){return r0.h.indexOf(c)>-1})))opts.push(r0)}
    for(var tr2=0;opts.length<4&&tr2<200;tr2++){var r=GM.all[Math.floor(Math.random()*GM.all.length)];if(okOpt(r))opts.push(r)}
    opts=shuf(opts);GM.q=q;
    $('plPrompt').innerHTML=GM.mode==='listen'?'<button class="btn" type="button" data-speak="'+esc(q.h)+'">🔊</button>':'<span lang="zh">'+esc(q.h)+'</span>';
    if(GM.mode==='listen')speak(q.h);
    $('plOpts').innerHTML=opts.map(function(o){return '<button class="btn ghost" type="button" data-opt="'+esc(o.h)+'"'+(GM.mode==='listen'?' lang="zh"':'')+'>'+esc(GM.mode==='listen'?o.h:mn(o.m))+'</button>'}).join('');
  }
  /* ---------- Бичих дасгал: иероглифыг зураасны дарааллаар, гаргалгүйгээр бичнэ ---------- */
  function wrStop(){try{if(GM&&GM.hw)GM.hw.cancelQuiz()}catch(e){}if(GM)GM.hw=null}
  function wrWrite(){
    var g=GM;if(!g||g.mode!=='write')return;
    loadHW(function(){
      if(GM!==g)return;
      var ch=g.chars[g.wi],box=$('wBox');if(!box||!ch)return;
      box.innerHTML='';g.hinted=false;
      $('plBuilt').style.color='';
      $('plBuilt').textContent=(g.chars.length>1?(g.wi+1)+' / '+g.chars.length+' · ':'')+T('wrHint');
      try{
        var nx=g.src[g.i+1],nc=g.wi+1<g.chars.length?g.chars[g.wi+1]:(nx?Array.from(nx.h)[0]:null);
        if(nc&&window.HanziWriter&&HanziWriter.loadCharacterData)HanziWriter.loadCharacterData(nc).catch(function(){});
      }catch(e){}
      g.hw=HanziWriter.create('wBox',ch,{width:240,height:240,padding:12,showOutline:false,showCharacter:false,strokeColor:cssv('--fg'),outlineColor:cssv('--line'),highlightColor:cssv('--accent'),drawingColor:cssv('--fg'),
        onLoadCharDataError:function(){if(GM===g){$('plBuilt').style.color='var(--bad)';$('plBuilt').textContent=T('wrErr')}}});
      g.hw.quiz({showHintAfterMisses:3,onComplete:function(sm){
        if(GM!==g)return;
        g.wm+=(sm&&sm.totalMistakes)||0;g.wi++;
        if(g.wi<g.chars.length){setTimeout(function(){if(GM===g)wrWrite()},500);return}
        var ok=g.wm<=2*g.chars.length;
        $('plBuilt').style.color=ok?'var(--ok)':'var(--bad)';
        $('plBuilt').textContent=(ok?'✓ ':'✗ ')+g.q.h+(g.wm?' · '+g.wm+'×':'');
        if(ok){g.ok++;missOk(g.q.h)}else{gMiss(g.q);srsGrade(g.q.h,0)}
        g.lock=1;setTimeout(function(){if(GM!==g)return;g.lock=0;g.i++;nextQ()},ok?900:1700);
      }});
    });
  }
  /* ---------- Хэлэх дасгал: микрофоноор хятад дуудлага шалгах ---------- */
  var SRC=window.SpeechRecognition||window.webkitSpeechRecognition;
  (function(){var sp=document.querySelector('[data-game="speak"]');if(sp&&!SRC)sp.hidden=true})();
  function micStop(){try{if(GM&&GM.rec)GM.rec.abort()}catch(e){}if(GM)GM.rec=null}
  function micNext(g,ms){setTimeout(function(){if(GM!==g)return;g.lock=0;g.i++;nextQ()},ms)}
  function micJudge(al){
    var g=GM,t=g.q.h.replace(/[^\u4e00-\u9fff]/g,''),best=0,heard=al[0]||'';
    al.forEach(function(s){
      var c=s.replace(/[^\u4e00-\u9fff]/g,'');if(!c)return;
      var sc=c.indexOf(t)>-1?1:dkLcs(c,t).n/Math.max(t.length,c.length);
      if(sc>best){best=sc;heard=s}
    });
    var need=t.length<=2?1:.75,ok=!t||best>=need;g.rec=null;
    $('plBuilt').style.color=ok?'var(--ok)':'var(--bad)';
    if(ok){$('plBuilt').textContent='✓ '+heard;g.ok++;missOk(g.q.h);g.lock=1;micNext(g,900)}
    else if(++g.tries<2){g.lock=0;$('plBuilt').textContent=T('micHeard')+' '+(heard||'—')+' · '+T('micRetry')}
    else{gMiss(g.q);srsGrade(g.q.h,0);g.lock=1;$('plBuilt').textContent=(heard||'—')+'  →  '+g.q.h;micNext(g,1800)}
  }
  function micStart(){
    if(!SRC){toast(T('micErr'),'oops');return}
    var g=GM,r=new SRC(),got=false;
    r.lang='zh-CN';r.interimResults=false;r.maxAlternatives=5;r.continuous=false;
    g.rec=r;g.lock=1;$('plBuilt').style.color='';$('plBuilt').textContent=T('micListen');
    r.onresult=function(ev){
      if(GM!==g)return;got=true;var al=[];
      try{for(var i=0;i<ev.results[0].length;i++)al.push(ev.results[0][i].transcript)}catch(x){}
      micJudge(al);
    };
    r.onerror=function(ev){
      if(GM!==g||ev.error==='no-speech'||ev.error==='aborted')return;
      got=true;g.lock=0;g.rec=null;toast(T('micErr'),'oops');$('plBuilt').textContent=T('micTap');
    };
    r.onend=function(){if(GM!==g||got)return;g.lock=0;g.rec=null;$('plBuilt').textContent=T('micRetry')};
    try{r.start()}catch(x){g.lock=0;g.rec=null;toast(T('micErr'),'oops')}
  }
  document.addEventListener('click',function(e){
    var b=e.target.closest('[data-goplay]');if(b){showTab('play');return}
    b=e.target.closest('[data-game]');if(b){startGame(b.dataset.game);return}
    if(e.target.closest('#plBack')){micStop();wrStop();GM=null;$('plGame').hidden=true;$('plMenu').hidden=false;showTab('today');return}
    if(e.target.closest('#plQuit')){micStop();wrStop();clearInterval(SPT);var qw=GM&&GM.wrong;GM=null;missFlush();if(qw&&qw.length)showWrong(qw);$('plGame').hidden=true;$('plMenu').hidden=false;return}
    if(!GM)return;
    b=e.target.closest('[data-wskip]');if(b&&GM.mode==='write'){wrStop();GM.lock=0;GM.i++;nextQ();return}
    b=e.target.closest('[data-whint]');if(b&&GM.mode==='write'){if(GM.hw&&!GM.hinted){GM.hinted=true;GM.wm+=2;try{GM.hw.showOutline()}catch(x){}}return}
    b=e.target.closest('[data-micskip]');if(b&&GM.mode==='speak'){micStop();GM.lock=0;GM.i++;nextQ();return}
    b=e.target.closest('[data-mic]');if(b&&GM.mode==='speak'){if(!GM.lock)micStart();return}
    b=e.target.closest('[data-opt]');
    if(b&&!GM.lock){
      GM.lock=1;var ok=b.dataset.opt===GM.q.h;b.style.background=ok?'var(--ok)':'var(--bad)';b.style.color='#fff';
      if(!ok)document.querySelectorAll('#plOpts [data-opt]').forEach(function(x){if(x.dataset.opt===GM.q.h){x.style.background='var(--ok)';x.style.color='#fff'}});
      if(ok){GM.ok++;missOk(GM.q.h)}else{gMiss(GM.q);srsGrade(GM.q.h,0)}
      cmb(ok);b.classList.add(ok?'gpop':'gshake');
      if(GM.mode==='sprint'&&ok&&GM.combo>0&&GM.combo%5===0){GM.end+=3000;toast(T('sprBonus'),'cheer')}
      if(GM.mode!=='sprint'){$('plScore').textContent=scoreTxt();if(ok&&GM.combo>=3&&GM.combo%3===0)fxTone([784,988])}
      if(GM.mode==='cloze'){$('plBuilt').style.color=ok?'var(--ok)':'var(--bad)';$('plBuilt').textContent=(ok?'✓ ':'✗ ')+GM.q.z;try{speak(GM.q.z)}catch(e){}}
      else if(GM.mode==='mean'||GM.mode==='listen'){$('plBuilt').style.color='';$('plBuilt').innerHTML=revHtml(GM.q)}
      if(!ok&&GM.mode!=='sprint'){holdNext(GM);return}
      setTimeout(function(g0){return function(){if(GM!==g0)return;GM.lock=0;GM.i++;nextQ()}}(GM),GM.mode==='sprint'?(ok?150:600):GM.mode==='cloze'?(ok?1700:2700):(ok?900:1700));return;
    }
  });
  /* ---------- Laoshi-тай ярих: багш асууна, сурагч зөв хариултыг сонгоно (үнэгүй, AI биш) ---------- */
  var TKD=null,TK=null,TKS={py:true,tr:true},TKDONE={};
  try{var _t=JSON.parse(lget('hsk-tk')||'{}');if(typeof _t.py==='boolean')TKS.py=_t.py;if(typeof _t.tr==='boolean')TKS.tr=_t.tr;TKDONE=JSON.parse(lget('hsk-tkdone')||'{}')}catch(e){}
  function tkSave(){try{localStorage.setItem('hsk-tk',JSON.stringify(TKS));localStorage.setItem('hsk-tkdone',JSON.stringify(TKDONE))}catch(e){}}
  function tkClose(){var o=$('talkView');if(o)o.remove();document.body.style.overflow='';TK=null;try{window.speechSynthesis&&speechSynthesis.cancel()}catch(e){}}
  function tkLine(z,p,m){return '<span class="tkz" lang="zh">'+esc(z)+'</span>'+(p?'<span class="tkp">'+esc(p)+'</span>':'')+(m?'<span class="tkm">'+esc(m)+'</span>':'')}
  function tkView(){
    var o=$('talkView');if(!o){o=document.createElement('div');o.id='talkView';o.className='pdfview tkview';document.body.appendChild(o);document.body.style.overflow='hidden'}
    o.classList.toggle('nopy',!TKS.py);o.classList.toggle('notr',!TKS.tr);return o;
  }
  function tkBar(title){
    return '<div class="pdfbar"><b class="pdft">'+esc(title)+'</b><button class="btn small ghost" type="button" data-tkt="py" aria-pressed="'+TKS.py+'">拼</button><button class="btn small ghost" type="button" data-tkt="tr" aria-pressed="'+TKS.tr+'">译</button><button class="btn small" type="button" data-tkx="1" aria-label="close">✕</button></div>';
  }
  function tkList(){
    TK=null;var o=tkView();
    o.innerHTML=tkBar(T('talkT'))+'<div class="pgscroll tkscroll"><div class="hint" style="padding:4px 2px 10px">'+esc(T('talkSub'))+'</div><div class="tkgrid">'+TKD.map(function(sc){
      var d=TKDONE[sc.id];
      return '<button class="tkcard" type="button" data-tks="'+esc(sc.id)+'"><span class="tki">'+sc.i+'</span><b>'+esc(sc.t)+'</b><span class="hint">'+esc(T('talkLv',{l:sc.lv}))+' · '+sc.turns.length+(d!=null?' · ✓ '+d+'/'+sc.turns.length:'')+'</span></button>'}).join('')+'</div></div>';
  }
  function tkBub(side,html,cls){
    var sc=$('tkChat');if(!sc)return null;var d=document.createElement('div');d.className='tkb '+side+(cls?' '+cls:'');d.innerHTML=html;sc.appendChild(d);sc.scrollTop=sc.scrollHeight;return d;
  }
  function tkStart(id){
    var sc=TKD.filter(function(x){return x.id===id})[0];if(!sc)return;
    TK={sc:sc,i:0,first:0,tries:0,lock:0};var o=tkView();
    o.innerHTML=tkBar(sc.i+' '+sc.t)+'<div class="pgscroll tkscroll" id="tkChat"></div><div class="tkopts" id="tkOpts"></div>';
    tkAsk();
  }
  function tkAsk(){
    var t=TK.sc.turns[TK.i];TK.tries=0;TK.lock=0;
    var b=tkBub('t','<span class="tkav">老师</span><div>'+tkLine(t.z,t.p,t.m)+'<button class="tkspk" type="button" data-tksp="'+esc(t.z)+'" aria-label="listen">🔊</button></div>');
    try{speak(t.z)}catch(e){}
    $('tkOpts').innerHTML=shuf(t.o.slice()).map(function(x,k){return '<button class="tkopt" type="button" data-tko="'+(t.o.indexOf(x))+'">'+tkLine(x.z,x.p,x.m)+'</button>'}).join('');
  }
  function tkPick(k,btn){
    if(!TK||TK.lock)return;var t=TK.sc.turns[TK.i],x=t.o[k];
    if(x.ok){
      TK.lock=1;if(!TK.tries)TK.first++;
      tkBub('u',tkLine(x.z,x.p,x.m));$('tkOpts').innerHTML='';
      var re=['很好！','对了！','说得好！','没错！'][Math.floor(Math.random()*4)];
      setTimeout(function(){if(!TK)return;
        tkBub('t','<span class="tkav">老师</span><div>'+tkLine(re,'',TK.tries?'':'👍')+'</div>');
        setTimeout(function(){if(!TK)return;TK.i++;if(TK.i<TK.sc.turns.length)tkAsk();else tkEnd()},800)},500);
    }else{
      TK.tries++;btn.disabled=true;btn.classList.add('bad','gshake');
      tkBub('t','<span class="tkav">老师</span><div class="tkh">'+esc(x.h||T('talkHint'))+'</div>','hint');
    }
  }
  function tkEnd(){
    var sc=TK.sc,n=sc.turns.length,a=TK.first,xp=a*10+(a===n?10:0);
    if(hasProfile())addXp(xp);if(a===n)fxWin('small');
    if(TKDONE[sc.id]==null||TKDONE[sc.id]<a){TKDONE[sc.id]=a;tkSave()}
    tkBub('t','<span class="tkav">老师</span><div><b>'+esc(T('talkRes',{a:a,b:n,x:hasProfile()?xp:0}))+'</b></div>');
    $('tkOpts').innerHTML='<div class="row"><button class="btn" type="button" data-tks="'+esc(sc.id)+'">'+esc(T('talkAgain'))+'</button><button class="btn ghost" type="button" data-tkl="1">'+esc(T('talkBack'))+'</button></div>';
  }
  function talkOpen(){
    var go=function(){tkList()};
    if(TKD){go();return}
    fetch('data/talk.json').then(function(r){return r.json()}).then(function(d){TKD=d.sc;go()}).catch(function(){toast(T('tConnErr'),'oops')});
  }
  document.addEventListener('click',function(e){
    var b;
    if(e.target.closest('[data-talk]')){talkOpen();return}
    if(!$('talkView'))return;
    if(e.target.closest('[data-tkx]')){tkClose();return}
    if(e.target.closest('[data-tkl]')){tkList();return}
    if((b=e.target.closest('[data-tkt]'))){var k=b.dataset.tkt;TKS[k]=!TKS[k];tkSave();$('talkView').classList.toggle(k==='py'?'nopy':'notr',!TKS[k]);b.setAttribute('aria-pressed',String(TKS[k]));return}
    if((b=e.target.closest('[data-tks]'))){tkStart(b.dataset.tks);return}
    if((b=e.target.closest('[data-tksp]'))){try{speak(b.dataset.tksp)}catch(x){}return}
    if((b=e.target.closest('[data-tko]'))){tkPick(+b.dataset.tko,b)}
  });
  /* гараас хариулах: 1-4 (эсвэл a-d) сонголт, Esc гарах — компьютер дээр хурдан тоглоход */
  document.addEventListener('keydown',function(e){
    if(!GM||GM.lock||e.ctrlKey||e.metaKey||e.altKey||/INPUT|TEXTAREA|SELECT/.test((e.target||{}).tagName||''))return;
    var k=e.key,n=/^[1-4]$/.test(k)?+k-1:'abcd'.indexOf(String(k).toLowerCase());
    if(n<0||String(k).length!==1)return;
    var bs=document.querySelectorAll('#plOpts [data-opt],#plOpts [data-topt]');
    if(bs[n]){e.preventDefault();bs[n].click()}
  });
  $('plBack')&&0;
  function gMiss(q){missAdd(q);if(GM&&q&&q.h){var a=GM.wrong=GM.wrong||[];if(!a.some(function(x){return x.h===q.h}))a.push(q)}}
  function showWrong(a){var el=$('plWrong');if(!el)return;if(!a||!a.length){el.hidden=true;return}
    el.innerHTML='<b>'+esc(T('plWrongT'))+'</b>'+a.slice(0,12).map(function(q){return '<div class="pw"><span lang="zh" class="pwh">'+esc(q.h||q.z||'')+'</span><span class="pwp">'+esc(q.p||'')+'</span><span class="pwm">'+esc(mn(q.m)||'')+'</span></div>'}).join('');el.hidden=false}
  function scoreTxt(){return '✓ '+GM.ok+((GM.combo||0)>=3?' · 🔥 '+GM.combo:'')}
  function cmb(ok){if(GM)GM.combo=ok?(GM.combo||0)+1:0}

  /* ---------- Өгүүлбэр угсрах: өгүүлбэрийг үгээр нь хувааж, санамсаргүй дарааллаар гаргана. Дарж зөв дарааллаар нь байрлуулна ---------- */
  var SBW=null;
  function sbWords(){
    if(!SBW){SBW={};try{hskPool().forEach(function(x){var h=String(x.h||'').replace(/[^一-鿿]/g,'');if(h.length>1&&h.length<=4)SBW[h]=1})}catch(e){}}
    return SBW;
  }
  function sbSplit(z){
    var s=String(z).replace(/[^一-鿿]/g,''),W=sbWords(),out=[],i=0;
    while(i<s.length){
      var w=null;
      for(var n=Math.min(4,s.length-i);n>=2;n--){if(W[s.substr(i,n)]){w=s.substr(i,n);break}}
      if(!w)w=s.charAt(i);
      out.push(w);i+=w.length;
    }
    /* хэт олон хэсэг болбол хамгийн богино хоёр зэрэгцээг нэгтгэнэ (дээд тал нь 9 хэсэг) */
    while(out.length>9){
      var bi=0,bl=99;
      for(var k=0;k<out.length-1;k++){var l=out[k].length+out[k+1].length;if(l<bl){bl=l;bi=k}}
      out.splice(bi,2,out[bi]+out[bi+1]);
    }
    if(out.length<3&&s.length>=3)out=Array.from(s);
    return out;
  }
  function sbPool(){
    var sel=plLvSel(),lv=sel||(S.profile&&S.profile.level)||3,L={},out=[],seen={},X=(window.DATA&&DATA.EXD)||{};
    try{hskPool().forEach(function(x){L[x.h]=x.l})}catch(e){}
    function add(z,m,l,ex){
      var a=String(z||'').replace(/[^一-鿿]/g,'');
      if(a.length<4||seen[a])return;seen[a]=1;
      var o=ex||{};o.z=z;o.m=m;o.l=l;out.push(o);
    }
    Object.keys(X).forEach(function(h){var l=L[h];if(l&&l<=lv&&X[h]&&X[h][0])add(X[h][0],X[h][1],l)});
    gramList().forEach(function(g){if(g.z&&g.l<=lv)add(g.z,g.t,g.l,{k:g.k,t:g.t})});
    var inBand=function(o){return sel?o.l===lv:o.l>=lv-1},near=out.filter(inBand),far=out.filter(function(o){return !inBand(o)}),res=shuf(near).slice(0,6);
    if(res.length<6)res=res.concat(shuf(far).slice(0,6-res.length));
    return res;
  }
  function sbStart(q){
    var g=GM;
    if(!q.tl){q.a=String(q.z).replace(/[^一-鿿]/g,'');q.tl=sbSplit(q.z)}
    g.q=q;g.ans=q.a;g.hint=0;g.placed=[];g.last=-1;g.lock=0;g.state='';
    var tiles=q.tl.map(function(t,k){return {id:k,t:t}}),sh=shuf(tiles),n=0;
    while(n++<6&&tiles.length>1&&sh.map(function(x){return x.t}).join('')===q.a)sh=shuf(tiles);
    g.tiles=sh;
    $('plPrompt').innerHTML='<span class="sb-tr">'+esc((q.k?gLoc(q,'t'):q.m)||'')+'</span>';
    sbRender();
  }
  function sbRender(){
    var g=GM;if(!g||g.mode!=='build')return;
    var by={},used={},dis=g.lock?' disabled':'';
    g.tiles.forEach(function(x){by[x.id]=x});g.placed.forEach(function(id){used[id]=1});
    var sl=g.placed.length?g.placed.map(function(id){return '<button class="tile'+(id===g.last?' in':'')+'" type="button" data-sbp="'+id+'" lang="zh"'+dis+'>'+esc(by[id].t)+'</button>'}).join(''):'<span class="sb-ph">'+esc(T('sbTap'))+'</span>';
    var bk=g.tiles.map(function(x){return used[x.id]?'<span class="tile ghost" aria-hidden="true">'+esc(x.t)+'</span>':'<button class="tile" type="button" data-sbt="'+x.id+'" lang="zh"'+dis+'>'+esc(x.t)+'</button>'}).join('');
    $('plOpts').innerHTML='<div class="sb-slots'+(g.state?' '+g.state:'')+'" lang="zh">'+sl+'</div><div class="sb-bank">'+bk+'</div>'+
      '<div class="sb-tools"><button class="btn ghost small" type="button" data-sbundo="1" aria-label="↩"'+dis+'>↩</button><button class="btn ghost small" type="button" data-sbreset="1" aria-label="⟲"'+dis+'>⟲</button><button class="btn ghost small" type="button" data-sbhint="1" aria-label="💡"'+dis+'>💡</button></div>';
  }
  function sbText(g){var by={};g.tiles.forEach(function(x){by[x.id]=x});return g.placed.map(function(id){return by[id].t}).join('')}
  /* Буруу хариулсны дараа автоматаар шилжихгүй: сурагч алдаагаа уншаад «Дараагийнх» дарна */
  function holdNext(g){
    var b=document.createElement('button');b.type='button';b.className='btn small';b.id='plNext';
    b.style.cssText='display:block;margin:10px auto 0;font-family:inherit;font-size:1rem';
    b.textContent=T('plNext');
    b.addEventListener('click',function(){if(GM!==g||!g.lock)return;g.lock=0;g.state='';g.i++;nextQ()});
    $('plBuilt').appendChild(b);
    try{b.focus({preventScroll:true})}catch(e){}
  }
  function sbCheck(){
    var g=GM,ok=sbText(g)===g.ans;
    g.lock=1;g.state=ok?'ok':'no';
    if(ok&&!g.hint)g.ok++;
    cmb(ok&&!g.hint);$('plScore').textContent=scoreTxt();
    $('plBuilt').style.color=ok?'var(--ok)':'var(--bad)';
    $('plBuilt').textContent=(ok?'✓ ':'✗ ')+g.q.z;
    if(ok){fxTone([659,880]);try{speak(g.q.z)}catch(e){}}
    sbRender();
    if(ok)setTimeout(function(){if(GM!==g)return;g.lock=0;g.state='';g.i++;nextQ()},1600);
    else{
      var mm=(g.q.k?gLoc(g.q,'t'):g.q.m)||'';
      if(mm){var sp=document.createElement('div');sp.style.cssText='font-size:.95rem;color:var(--muted,inherit);font-family:inherit;margin-top:4px';sp.textContent=mm;$('plBuilt').appendChild(sp)}
      holdNext(g);
    }
  }
  document.addEventListener('click',function(e){
    var g=GM;if(!g||g.mode!=='build'||g.lock||!e.target.closest)return;
    var t=e.target.closest('[data-sbt],[data-sbp],[data-sbundo],[data-sbreset],[data-sbhint]');if(!t)return;
    if(t.dataset.sbt!=null){var id=+t.dataset.sbt;g.placed.push(id);g.last=id;sbRender();if(g.placed.length===g.tiles.length)sbCheck();return}
    if(t.dataset.sbp!=null){var id2=+t.dataset.sbp;g.placed=g.placed.filter(function(x){return x!==id2});g.last=-1;sbRender();return}
    if(t.dataset.sbundo!=null){g.placed.pop();g.last=-1;sbRender();return}
    if(t.dataset.sbreset!=null){g.placed=[];g.last=-1;sbRender();return}
    if(t.dataset.sbhint!=null){
      var cur=sbText(g);if(g.ans.indexOf(cur)!==0){g.placed=[];cur=''}
      var need=null;
      g.tiles.forEach(function(x){if(need===null&&g.placed.indexOf(x.id)<0&&g.ans.substr(cur.length,x.t.length)===x.t)need=x.id});
      if(need!==null){g.placed.push(need);g.last=need;g.hint++;sbRender();if(g.placed.length===g.tiles.length)sbCheck()}
    }
  });
  /* ---------- Тоглоомын түвшин сонгогч ---------- */
  function renderPlLv(){
    var el=$('plLv');if(!el)return;var s=plLvSel();
    el.innerHTML=['0','1','2','3','4','5','6'].map(function(v){return '<button class="chip" type="button" data-pl="'+v+'" aria-pressed="'+(String(s)===v?'true':'false')+'">'+(v==='0'?esc(T('plLvAuto')):'HSK '+v)+'</button>'}).join('');
  }
  /* хариулсны дараа иероглиф · пиньин(тоны өнгөтэй) · утгыг харуулна */
  function revHtml(q){return '<span lang="zh">'+esc(q.h)+'</span> <span class="rvb">'+toneHtml(q.p||'')+' · '+esc(mn(q.m))+'</span>'}

  /* ---------- Пиньиний тон солих (тон таах тоглоомд зориулсан төөрөгдүүлэгч хариулт) ---------- */
  var TMARK={a:'āáǎà',e:'ēéěè',i:'īíǐì',o:'ōóǒò',u:'ūúǔù','ü':'ǖǘǚǜ'};
  function toneSyl(plain,t){
    if(!t)return plain;
    var idx=plain.indexOf('a');
    if(idx<0)idx=plain.indexOf('e');
    if(idx<0&&plain.indexOf('ou')>-1)idx=plain.indexOf('ou');
    if(idx<0){for(var k=plain.length-1;k>=0;k--){if('iouü'.indexOf(plain.charAt(k))>-1){idx=k;break}}}
    if(idx<0)return plain;
    var ch=plain.charAt(idx);
    return plain.slice(0,idx)+TMARK[ch][t-1]+plain.slice(idx+1);
  }
  /* py → {parts, syl:[{k,plain,tone}]} эсвэл null (слог тусгаарлаж чадахгүй бол) */
  function pyParse(py){
    var parts=String(py).normalize('NFC').split(/([A-Za-zÀ-ɏḿ]+)/),syl=[],bad=false;
    parts.forEach(function(p,k){
      if(k%2===0||bad)return;
      var pl=Array.from(p.toLowerCase()).map(function(c){return PY_TONE[c]||c}).join('').replace(/([jqxy])u(?=e|an|n|$)/g,'$1ü'),
          sg=(pl.length===p.length&&/^[a-zü]+$/.test(pl))?pySeg(pl):null;
      if(!sg||!sg.a.length){bad=true;return}
      var pos=0;
      sg.a.forEach(function(x){var L=x[0].length+x[1].length;syl.push({k:k,plain:pl.substr(pos,L),tone:toneOfStr(p.substr(pos,L))});pos+=L});
    });
    return bad||!syl.length?null:{parts:parts,syl:syl};
  }
  function pyBuild(ps,tones){
    var out=ps.parts.slice(),by={};
    ps.syl.forEach(function(s,i){(by[s.k]=by[s.k]||[]).push(toneSyl(s.plain,tones[i]))});
    Object.keys(by).forEach(function(k){
      var t=by[k].join(''),o=ps.parts[k];
      if(o.charAt(0)!==o.charAt(0).toLowerCase())t=t.charAt(0).toUpperCase()+t.slice(1);
      out[k]=t;
    });
    return out.join('');
  }
  function pyVariants(py){
    var ps=pyParse(py);if(!ps||ps.syl.length>3||ps.syl.every(function(s){return !s.tone}))return null;
    var base=ps.syl.map(function(s){return s.tone}),set={},list=[];
    function add(tones){var s=pyBuild(ps,tones);if(s!==py&&!set[s]){set[s]=1;list.push(s)}}
    ps.syl.forEach(function(s,i){
      if(!s.tone)return;
      for(var t=1;t<=4;t++){if(t!==s.tone){var a=base.slice();a[i]=t;add(a)}}
    });
    if(ps.syl.length>1){
      var tries=0;
      while(list.length<6&&tries++<30){var b=base.map(function(t){return t?1+Math.floor(Math.random()*4):0});add(b)}
    }
    return list.length>=3?shuf(list).slice(0,3):null;
  }

  /* ---------- 🎼 Тон таах ---------- */
  function tnPool(P){
    var pool=shuf(P.all.filter(function(w){return w.p&&w.m})),out=[],n=0;
    for(var i=0;i<pool.length&&out.length<10&&n<600;i++,n++){
      var v=pyVariants(pool[i].p);
      if(v)out.push({h:pool[i].h,p:pool[i].p,m:pool[i].m,v:v});
    }
    return out;
  }
  function tnStart(q){
    GM.q=q;GM.lock=0;
    $('plPrompt').innerHTML='<span lang="zh">'+esc(q.h)+'</span><div class="sb-tr" style="font-weight:600;color:var(--muted)">'+esc(mn(q.m))+'</div><button class="btn ghost small" type="button" data-speak="'+esc(q.h)+'" aria-label="🔊">🔊</button>';
    $('plOpts').innerHTML=shuf([q.p].concat(q.v)).map(function(o){return '<button class="btn ghost" type="button" data-topt="'+esc(o)+'">'+esc(o)+'</button>'}).join('');
    try{speak(q.h)}catch(e){}
  }

  /* ---------- ✏️ Хоосон нөхөх ---------- */
  function clPool(){
    var X=(window.DATA&&DATA.EXD)||{};
    function build(lvs){
      var L={},byLen={},out=[];
      hskPool().forEach(function(x){L[x.h]=x;if(lvs.indexOf(x.l)>-1&&hM(x.h))(byLen[x.h.length]=byLen[x.h.length]||[]).push(x)});
      Object.keys(X).forEach(function(h){
        var x=L[h];
        if(x&&lvs.indexOf(x.l)>-1&&X[h]&&X[h][0]&&X[h][0].indexOf(h)>-1&&hM(h))out.push({h:h,p:hP(h,x.p),m:hM(h),z:X[h][0],zt:X[h][1],l:x.l});
      });
      out=shuf(out).slice(0,8);
      var all=[].concat.apply([],Object.keys(byLen).map(function(k){return byLen[k]}));
      out.forEach(function(q){
        var same=byLen[q.h.length]||[],opts=[q.h],t=0;
        while(opts.length<4&&t++<60){var r=(same.length>4?same:all)[Math.floor(Math.random()*(same.length>4?same:all).length)];if(r&&opts.indexOf(r.h)<0&&q.z.indexOf(r.h)<0)opts.push(r.h)}
        q.opts=opts;
      });
      return out.filter(function(q){return q.opts.length===4});
    }
    var r=build(gLevels());
    return r.length>=4?r:build([1,2,3,4,5,6]);
  }
  function clStart(q){
    GM.q=q;GM.lock=0;
    $('plPrompt').innerHTML='<div lang="zh" style="font-size:1.7rem;line-height:1.5;font-weight:700">'+esc(q.z.replace(q.h,'＿＿'))+'</div><div class="sb-tr" style="font-weight:600;color:var(--muted)">'+esc(q.zt||'')+'</div>';
    $('plOpts').innerHTML=shuf(q.opts).map(function(o){return '<button class="btn ghost" type="button" data-opt="'+esc(o)+'" lang="zh">'+esc(o)+'</button>'}).join('');
  }

  /* ---------- 🃏 Хос олох (санах ойн тоглоом) ---------- */
  function mcPool(P){
    var base=P.mine.length>=12?P.mine:P.all,seenH={},seenM={},out=[];
    shuf(base).forEach(function(w){
      var m=mn(w.m);
      if(out.length>=12||!w.h||!m||seenH[w.h]||seenM[m]||m.length>28)return;
      seenH[w.h]=1;seenM[m]=1;out.push(w);
    });
    return out;
  }
  function mcStart(round){
    var cards=[];
    round.forEach(function(w){cards.push({id:w.h,t:'h',w:w});cards.push({id:w.h,t:'m',w:w})});
    GM.mc={cards:shuf(cards),open:[],done:0,moves:0,lock:0};GM.lock=0;
    mcRender();
  }
  function mcRender(){
    var g=GM&&GM.mc;if(!g)return;
    $('plPrompt').innerHTML='<span class="sb-tr">'+esc(T('mcHint'))+' · '+esc(T('mcMoves'))+': '+g.moves+'</span>';
    $('plOpts').innerHTML='<div class="mgrid">'+g.cards.map(function(c,i){
      var on=c.open||c.ok;
      return '<button type="button" class="mc'+(c.ok?' ok':c.open?' on':'')+(c.bad?' bad':'')+'" data-mc="'+i+'"'+(c.t==='h'?' lang="zh"':'')+'>'+(on?(c.t==='h'?'<span class="mh">'+esc(c.w.h)+'</span>':'<span class="mm">'+esc(mn(c.w.m))+'</span>'):'<span class="mq">?</span>')+'</button>';
    }).join('')+'</div>';
  }

  document.addEventListener('click',function(e){
    var t=e.target;if(!t||!t.closest)return;
    var pl=t.closest('[data-pl]');
    if(pl){lset('hsk-pl',pl.dataset.pl);renderPlLv();return}
    var g=GM;if(!g)return;
    /* Тон таах */
    var to=t.closest('[data-topt]');
    if(to&&g.mode==='tone'&&!g.lock){
      g.lock=1;var ok=to.dataset.topt===g.q.p;
      document.querySelectorAll('#plOpts [data-topt]').forEach(function(x){if(x.dataset.topt===g.q.p){x.style.background='var(--ok)';x.style.color='#fff'}});
      if(!ok){to.style.background='var(--bad)';to.style.color='#fff'}
      to.classList.add(ok?'gpop':'gshake');
      if(ok){g.ok++;missOk(g.q.h)}else{gMiss(g.q);srsGrade(g.q.h,0)}
      cmb(ok);$('plScore').textContent=scoreTxt();if(ok&&g.combo>=3&&g.combo%3===0)fxTone([784,988]);
      $('plBuilt').style.color='';$('plBuilt').innerHTML=revHtml(g.q);
      if(!ok){holdNext(g);return}
      setTimeout(function(){if(GM!==g)return;g.lock=0;g.i++;nextQ()},1100);
      return;
    }
    /* Хос олох */
    var mc=t.closest('[data-mc]');
    if(mc&&g.mode==='match'&&g.mc&&!g.mc.lock){
      var m=g.mc,c=m.cards[+mc.dataset.mc];
      if(!c||c.ok||c.open)return;
      c.open=true;m.open.push(+mc.dataset.mc);
      if(c.t==='h'){try{speak(c.w.h)}catch(err){}}
      if(m.open.length===2){
        m.moves++;
        var a=m.cards[m.open[0]],b=m.cards[m.open[1]];
        if(a.id===b.id&&a.t!==b.t){
          a.ok=b.ok=true;a.open=b.open=false;m.open=[];m.done++;fxTone([659,880]);
          mcRender();
          if(m.done===m.cards.length/2){
            g.ok++;$('plScore').textContent=scoreTxt();
            setTimeout(function(){if(GM!==g)return;g.i++;nextQ()},1000);
          }
        }else{
          m.lock=1;a.bad=b.bad=true;mcRender();
          setTimeout(function(){if(GM!==g)return;a.open=b.open=false;a.bad=b.bad=false;m.open=[];m.lock=0;mcRender()},850);
        }
        return;
      }
      mcRender();
    }
  });

  /* тоглоомын цэсийн товчнуудыг «дүрс + нэр» тайл болгоно */
  function decorateMenu(){
    try{document.querySelectorAll('#plMenu [data-game]').forEach(function(b){
      var m=/^(\p{Extended_Pictographic}️?)\s*([\s\S]*)$/u.exec(b.textContent||'');
      if(!m)return;
      b.textContent='';
      var a=document.createElement('span');a.className='gi';a.textContent=m[1];
      var c=document.createElement('span');c.textContent=m[2];
      b.appendChild(a);b.appendChild(c);
    })}catch(err){}
  }
  /* ---------- HSK test mode (questions drawn from every word of a level) ---------- */
  var EX=null,exTimer=null,exSel={lv:5,n:20,mode:'word'};
  function exPool(lv){var o=[];(HR()[lv]||'').split(',').forEach(function(it){var a=it.split('|'),m=hM(a[0]);if(m)o.push({h:a[0],p:hP(a[0],a[1]),m:m})});return o}
  function exShow(id){['plMenu','plGame','exSetup','exRun','exDone'].forEach(function(k){$(k).hidden=k!==id})}
  function exReset(){clearInterval(exTimer);EX=null;['exSetup','exRun','exDone'].forEach(function(k){$(k).hidden=true})}
  function exTime(s){return Math.floor(s/60)+':'+('0'+s%60).slice(-2)}
  function exBuild(lv,fixed,n){
    var pool=exPool(lv),src=fixed||shuf(pool).slice(0,n),types=['zh2mn','mn2zh','listen'];
    return src.map(function(w){
      var opts=[w],g=0;
      while(opts.length<4&&g++<300){var r=pool[Math.floor(Math.random()*pool.length)];if(!opts.some(function(o){return o.h===r.h||mn(o.m)===mn(r.m)}))opts.push(r)}
      return {w:w,type:types[Math.floor(Math.random()*3)],opts:shuf(opts),pick:null};
    });
  }
  function mockBuild(lv,n){
    var X=(window.DATA&&DATA.EXD)||{},tts=!!window.speechSynthesis;
    var nR=Math.round(n/3),nL=tts?Math.round(n/3):0,used={},qs=[],pool=exPool(lv);
    function lvW(h){var it=hskLookup(h);return it?it.l:99}
    function wo(h){var it=hskLookup(h)||{};return {h:h,p:hP(h,it.p),m:hM(h)}}
    var keys=Object.keys(X).filter(function(h){return X[h]&&X[h][0]&&X[h][1]&&hM(h)&&lvW(h)<=lv});
    var cand=shuf(keys.filter(function(h){return lvW(h)===lv})).concat(shuf(keys.filter(function(h){return lvW(h)!==lv})));
    function take(k){var out=[];while(out.length<k&&cand.length){var h=cand.shift();if(used[h])continue;used[h]=1;out.push(h)}return out}
    function trOpts(h){
      var o=[{h:h,t:X[h][1]}],g=0;
      while(o.length<4&&g++<300){var r=keys[Math.floor(Math.random()*keys.length)];if(r!==h&&!o.some(function(x){return x.t===X[r][1]}))o.push({h:r,t:X[r][1]})}
      return o.length<4?null:shuf(o);
    }
    function wOpts(w,z){
      var o=[w],g=0;
      while(o.length<4&&g++<300){var r=pool[Math.floor(Math.random()*pool.length)];if(!o.some(function(x){return x.h===r.h||mn(x.m)===mn(r.m)})&&(!z||z.indexOf(r.h)<0))o.push(r)}
      return o.length<4?null:shuf(o);
    }
    take(nL).forEach(function(h){var o=trOpts(h);if(o)qs.push({w:wo(h),type:'sl',z:X[h][0],opts:o,pick:null,sec:'L'})});
    var nC=Math.ceil(nR/2),got=0;
    shuf(pool).forEach(function(w){
      if(got>=nC||used[w.h])return;
      var z=(X[w.h]&&X[w.h][0])||exSent(w.h);if(!z||z.indexOf(w.h)<0)return;
      var o=wOpts(w,z);if(!o)return;
      used[w.h]=1;got++;qs.push({w:w,type:'cloze',z:z.replace(w.h,'＿＿'),opts:o,pick:null,sec:'R'});
    });
    take(nR-got).forEach(function(h){var o=trOpts(h);if(o)qs.push({w:wo(h),type:'tr',z:X[h][0],opts:o,pick:null,sec:'R'})});
    var vt=['zh2mn','mn2zh'];
    shuf(pool.filter(function(w){return !used[w.h]})).some(function(w){
      if(qs.length>=n)return true;
      var o=wOpts(w);if(o){used[w.h]=1;qs.push({w:w,type:vt[Math.floor(Math.random()*2)],opts:o,pick:null,sec:'V'})}
      return false;
    });
    return qs;
  }
  function exSecHtml(){
    if(!EX||!EX.mock||!EX.secs)return '';
    var nm={L:'exSecL',R:'exSecR',V:'exSecV'};
    return '<div class="hint" style="text-align:center">'+['L','R','V'].filter(function(k){return EX.secs[k]}).map(function(k){return esc(T(nm[k]))+': '+EX.secs[k][0]+'/'+EX.secs[k][1]}).join(' · ')+'</div>';
  }
  function exOpen(){
    exSel.lv=exSel.lv||(S.profile&&S.profile.level)||5;
    exShow('exSetup');exSetup();
  }
  function exSetup(){
    var mk=exSel.mode==='mock',ns=mk?[15,30,45]:[10,20,40];
    if(ns.indexOf(exSel.n)<0)exSel.n=ns[1];
    $('exMode').innerHTML=[['word','exKW'],['mock','exKM']].map(function(k){return '<button class="chip" type="button" data-exmode="'+k[0]+'" aria-pressed="'+(exSel.mode===k[0])+'">'+esc(T(k[1]))+'</button>'}).join('');
    $('exHintT').textContent=T(mk?'exMockHint':'exHint');
    $('exLv').innerHTML=LEVELS.map(function(l){return '<button class="chip" type="button" data-exlv="'+l+'" aria-pressed="'+(exSel.lv===l)+'">HSK '+l+'</button>'}).join('');
    $('exN').innerHTML=ns.map(function(n){return '<button class="chip" type="button" data-exn="'+n+'" aria-pressed="'+(exSel.n===n)+'">'+n+'</button>'}).join('');
    var h=(S.profile&&S.profile.ex||[]).slice(-5).reverse();
    $('exHist').innerHTML=h.length?'<b>'+esc(T('exHistT'))+'</b><br>'+h.map(function(r){return (r.m?'🧪 ':'')+esc(fmt(parseIso(r.d)))+' · HSK '+r.lv+' · '+r.ok+'/'+r.n+' ('+Math.round(r.ok*100/r.n)+'%) · '+exTime(r.s)}).join('<br>'):'';
  }
  function exStart(fixed){
    var mock=exSel.mode==='mock'&&!fixed,qs=mock?mockBuild(exSel.lv,exSel.n):exBuild(exSel.lv,fixed,exSel.n);
    if(qs.length<(mock?6:2)){toast(T('tWords'),'oops');return}
    EX={lv:exSel.lv,qs:qs,i:0,t0:Date.now(),running:true,lock:0,mock:mock,limit:mock?qs.length*45:0};
    exShow('exRun');clearInterval(exTimer);
    function tick(){
      if(!EX||!EX.running)return;
      var el=Math.round((Date.now()-EX.t0)/1000);
      if(EX.limit){var left=Math.max(0,EX.limit-el);$('exT').textContent='⏳ '+exTime(left);$('exT').style.color=left<=60?'var(--bad)':'';if(left<=0)exFinish()}
      else $('exT').textContent='⏱ '+exTime(el);
    }
    exTimer=setInterval(tick,1000);$('exT').style.color='';
    $('exT').textContent=EX.limit?'⏳ '+exTime(EX.limit):'⏱ 0:00';exRender();
  }
  function exRender(){
    var q=EX.qs[EX.i],w=q.w,sc={L:'exSecL',R:'exSecR',V:'exSecV'},big='font-size:1.4rem;font-family:var(--font-han);font-weight:700;line-height:1.5';
    $('exQ').textContent=(EX.mock&&q.sec?T(sc[q.sec])+' · ':'')+(EX.i+1)+' / '+EX.qs.length;$('exBar').style.width=Math.round(EX.i/EX.qs.length*100)+'%';
    $('exPrompt').innerHTML=q.type==='sl'?'<button class="btn" type="button" data-speak="'+esc(q.z)+'">🔊</button>'
      :(q.type==='tr'||q.type==='cloze')?'<span lang="zh" style="'+big+'">'+esc(q.z)+'</span>'
      :q.type==='zh2mn'?'<span lang="zh">'+esc(w.h)+'</span>':q.type==='mn2zh'?'<span style="font-size:1.25rem;font-family:inherit;font-weight:700">'+esc(mn(w.m))+'</span>':'<button class="btn" type="button" data-speak="'+esc(w.h)+'">🔊</button>';
    if(q.type==='listen')speak(w.h);else if(q.type==='sl')speak(q.z);
    var zhO=q.type==='mn2zh'||q.type==='listen'||q.type==='cloze';
    $('exOpts').innerHTML=q.opts.map(function(o,k){return '<button class="btn ghost" type="button" data-exopt="'+k+'"'+(zhO?' lang="zh"':'')+'>'+esc((q.type==='sl'||q.type==='tr')?o.t:(zhO?o.h:mn(o.m)))+'</button>'}).join('');
  }
  function exRight(q){return q.pick!=null&&q.opts[q.pick].h===q.w.h}
  function exFinish(){
    if(!EX||!EX.running)return;
    clearInterval(exTimer);EX.running=false;try{speechSynthesis.cancel()}catch(e){}
    var n=EX.qs.length,ok=EX.qs.filter(exRight).length,sec=Math.round((Date.now()-EX.t0)/1000),pct=Math.round(ok*100/n);
    EX.ok=ok;EX.sec=sec;
    var hist=((S.profile&&S.profile.ex)||[]).slice(-29).concat([{d:TODAY,lv:EX.lv,n:n,ok:ok,s:sec,m:EX.mock?1:0}]);
    if(EX.mock){var secs={};EX.qs.forEach(function(q){var k=q.sec||'V';if(!secs[k])secs[k]=[0,0];secs[k][1]++;if(exRight(q))secs[k][0]++});EX.secs=secs}
    EX.qs.forEach(function(q){if(q.pick==null)return;if(exRight(q))missOk(q.w.h);else{missAdd(q.w);srsGrade(q.w.h,0)}});
    pPatch({ex:hist,miss:S.profile.miss||{},srs:S.profile.srs||{}});missDirty=false;var xp=ok*5+(EX.mock&&pct>=60?20:0);addXp(xp);
    exResult(pct,xp);
  }
  function exResult(pct,xp){
    if(pct>=80)fxWin(pct===100?'big':'small');
    var n=EX.qs.length,wrong=EX.qs.filter(function(q){return !exRight(q)}).map(function(q){return q.w});
    var own={};wordsArr().forEach(function(w){own[w.h]=1});
    var h='<div class="label">'+esc(T('exDoneT'))+' · HSK '+EX.lv+'</div>'+
      '<div style="text-align:center"><b style="font-family:var(--font-display);font-size:2.4rem">'+EX.ok+' / '+n+'</b><div class="muted">'+esc(T('exScore',{a:EX.ok,b:n,p:pct,t:exTime(EX.sec)}))+' · '+esc(T('exXp',{x:xp}))+'</div>'+
      '<div style="margin-top:6px">'+esc(wrong.length?T(pct>=60?'exPass':'exFail'):T('exAllRight'))+'</div></div>';
    h+=exSecHtml();
    if(wrong.length){
      h+='<h2>'+esc(T('exWrong',{n:wrong.length}))+'</h2><div class="list">'+wrong.map(function(w){
        return '<div class="w"><span class="h" lang="zh">'+esc(w.h)+'</span><span><span class="p">'+esc(w.p)+'</span><br><span class="m">'+esc(w.m)+'</span></span><span style="display:flex;flex-direction:column;gap:6px"><button class="x" type="button" data-speak="'+esc(w.h)+'">🔊</button>'+
          '<button class="x add'+(own[w.h]?' added':'')+'" type="button" data-exadd="'+esc(w.h)+'"'+(own[w.h]||!hasProfile()?' disabled':'')+'>'+(own[w.h]?'✓':'+')+'</button></span></div>';
      }).join('')+'</div>';
      h+='<button class="btn small" type="button" data-exam="addwrong" style="align-self:flex-start">'+esc(T('exAddAll'))+'</button><button class="btn" type="button" data-exam="retry">'+esc(T('exRetry'))+'</button>';
    }
    h+='<div class="row"><button class="btn'+(wrong.length?' ghost':'')+'" type="button" data-exam="again">'+esc(T('exAgain'))+'</button><button class="btn ghost" type="button" data-exam="menu">'+esc(T('plBack'))+'</button></div>';
    $('exDone').innerHTML=h;exShow('exDone');
  }
  function exAdd(list){
    var own={},n=0;wordsArr().forEach(function(w){own[w.h]=1});
    list.forEach(function(w){if(own[w.h]||!w.h)return;own[w.h]=1;addWord(w.h,w.p||'',w.m,'',TODAY,EX.lv);n++});
    if(n){syncSummary(TODAY);renderAll();toast(T('tAddedN',{n:n}),'cheer')}
  }
  document.addEventListener('click',function(e){
    if(e.target.closest('#plBack'))exReset();
    var b=e.target.closest('[data-exam]');
    if(b){
      var a=b.dataset.exam;
      if(a==='open'){exOpen();return}
      if(a==='start'){exStart();return}
      if(a==='menu'){exReset();exShow('plMenu');return}
      if(a==='quit'){exReset();exShow('plMenu');return}
      if(a==='again'){exOpen();return}
      if(a==='retry'&&EX){var ws=EX.qs.filter(function(q){return !exRight(q)}).map(function(q){return q.w});exSel.lv=EX.lv;exStart(ws);return}
      if(a==='addwrong'&&EX){exAdd(EX.qs.filter(function(q){return !exRight(q)}).map(function(q){return q.w}));exResult(Math.round(EX.ok*100/EX.qs.length),EX.ok*5);return}
    }
    b=e.target.closest('[data-exmode]');if(b){exSel.mode=b.dataset.exmode;exSetup();return}
    b=e.target.closest('[data-exlv]');if(b){exSel.lv=+b.dataset.exlv;exSetup();return}
    b=e.target.closest('[data-exn]');if(b){exSel.n=+b.dataset.exn;exSetup();return}
    b=e.target.closest('[data-exadd]');
    if(b&&EX){var w=EX.qs.filter(function(q){return q.w.h===b.dataset.exadd})[0];if(w){exAdd([w.w]);b.textContent='✓';b.disabled=true;b.classList.add('added')}return}
    b=e.target.closest('[data-exopt]');
    if(b&&EX&&EX.running&&!EX.lock){
      EX.lock=1;EX.qs[EX.i].pick=+b.dataset.exopt;b.style.background='var(--accent)';b.style.color='var(--on-accent)';
      setTimeout(function(){if(!EX)return;EX.lock=0;EX.i++;if(EX.i>=EX.qs.length)exFinish();else exRender()},250);
    }
  });
  /* ---------- stroke order / writing practice (HanziWriter, loaded on demand) ---------- */
  var WR=null,wrChars=[];
  function loadHW(cb){
    if(window.HanziWriter){cb();return}
    var sc=document.createElement('script');sc.src='js/vendor/hanzi-writer.min.js';
    sc.onload=cb;sc.onerror=function(){toast(T('wrErr'),'oops')};document.head.appendChild(sc);
  }
  function cssv(n){return getComputedStyle(document.documentElement).getPropertyValue(n).trim()||'#888'}
  function openWriter(t){
    wrChars=Array.from(t).filter(function(c){return /[\u4e00-\u9fff]/.test(c)});
    if(!wrChars.length)return;
    $('wrModal').hidden=false;loadHW(function(){showChar(0)});
  }
  function showChar(i){
    $('wrChips').innerHTML=wrChars.length>1?wrChars.map(function(c,k){return '<button class="btn small'+(k===i?'':' ghost')+'" type="button" data-wrc="'+k+'" lang="zh">'+esc(c)+'</button>'}).join(''):'';
    $('wrBox').innerHTML='';$('wrMsg').textContent='';
    WR=HanziWriter.create('wrBox',wrChars[i],{width:260,height:260,padding:14,showOutline:true,strokeColor:cssv('--fg'),outlineColor:cssv('--line'),radicalColor:cssv('--seal'),highlightColor:cssv('--accent'),strokeAnimationSpeed:1,delayBetweenStrokes:250,onLoadCharDataError:function(){$('wrMsg').textContent=T('wrErr')}});
    WR.animateCharacter();WR.cur=i;
  }
  document.addEventListener('click',function(e){
    var b=e.target.closest('[data-write]');if(b){openWriter(b.dataset.write);return}
    if(e.target.id==='wrModal'||e.target.closest('#wrClose')){$('wrModal').hidden=true;WR=null;return}
    b=e.target.closest('[data-wrc]');if(b){showChar(+b.dataset.wrc);return}
    if(!WR)return;
    if(e.target.closest('#wrAnim')){WR.cancelQuiz();WR.animateCharacter();return}
    if(e.target.closest('#wrQuiz')){
      $('wrMsg').textContent=T('wrHint');
      WR.quiz({onComplete:function(){
        $('wrMsg').textContent=T('wrDone');if(hasProfile())addXp(5);
        var n=WR.cur+1;if(n<wrChars.length)setTimeout(function(){if(WR)showChar(n)},900);
      }});
    }
  });
  /* ---------- classes & tasks (admin = teacher) ---------- */
  var CL={classes:[],members:[],tasks:[],done:[]},clOpen={};
  function renderClasses(){
    var el=$('clsAdmin');if(!el)return;if(!isOwner){el.hidden=true;return}el.hidden=false;
    var h='<h2>'+T('clsTitle')+'</h2><div class="row"><input id="clName" type="text" placeholder="'+esc(T('clName'))+'"><button class="btn" id="clAdd" type="button">+</button></div>';
    CL.classes.forEach(function(c){
      var mem=CL.members.filter(function(m){return m.class_id===c.id});
      h+='<div class="gm"><div class="between"><b>'+esc(c.name)+'</b><span class="badge">'+T('clCode')+': '+esc(c.code)+'</span></div><button class="btn ghost small" type="button" data-cmem="'+esc(c.id)+'">👥 '+mem.length+' '+T('clStud')+'</button>';
      if(clOpen[c.id])mem.forEach(function(m){
        var pp=P[m.uid]||{},dn=CL.tasks.filter(function(t){return t.class_id===c.id&&CL.done.some(function(x){return x.task_id===t.id&&x.uid===m.uid})}).length;
        h+='<div class="w" style="grid-template-columns:1fr auto"><span><b>'+esc(pp.nick||'?')+'</b><br><span class="hint">'+weekXp(pp.xpd)+' XP / 7 · ✓ '+dn+'</span></span><button class="btn small ghost" type="button" data-mdel="'+esc(c.id)+'|'+esc(m.uid)+'">✕</button></div>';
      });
      CL.tasks.filter(function(t){return t.class_id===c.id}).forEach(function(t){
        var d=CL.done.filter(function(x){return x.task_id===t.id});
        h+='<div class="w" style="grid-template-columns:1fr auto"><span><b>'+esc(t.title)+'</b> <span class="badge">'+t.xp+' XP</span><br><span class="hint">'+d.length+'/'+mem.length+' ✓ '+esc(d.map(function(x){return (P[x.uid]||{}).nick||'?'}).join(', '))+'</span></span><span><button class="btn small ghost" type="button" data-tedit="'+esc(t.id)+'">✎</button> <button class="btn small ghost" type="button" data-tdel="'+esc(t.id)+'">✕</button></span></div>';
      });
      h+='<button class="btn ghost small" type="button" data-tnew="'+esc(c.id)+'">+ '+T('tNew')+'</button></div>';
    });
    el.innerHTML=h;
  }
  function renderCls(){
    updateRemind();
    var el=$('taskCard');if(!el)return;
    if(!hasProfile()||mode!=='db'||isOwner){el.hidden=true;return}
    el.hidden=false;
    var mine=CL.members.filter(function(m){return m.uid===uid}).map(function(m){return m.class_id});
    var h='<h2>'+T('myTasks')+'</h2>';
    if(!mine.length)h+='<div class="hint">'+T('tNoCls')+'</div><div class="row"><input id="jcCode" type="text" autocapitalize="characters" placeholder="'+esc(T('joinPh'))+'"><button class="btn" id="jcBtn" type="button">'+T('joinBtn')+'</button></div>';
    CL.tasks.filter(function(t){return mine.indexOf(t.class_id)>-1}).forEach(function(t){
      var done=CL.done.some(function(x){return x.task_id===t.id&&x.uid===uid});
      h+='<div class="w" style="grid-template-columns:1fr auto"><span><b>'+esc(t.title)+'</b> <span class="badge">'+t.xp+' XP</span>'+(t.due?'<br><span class="hint">⏰ '+esc(t.due)+'</span>':'')+'</span>'+
        (done?'<span class="badge">✓</span>':'<button class="btn small" type="button" data-tdo="'+esc(t.id)+'">'+T(t.kind==='quiz'?'tStart':'tFinish')+'</button>')+'</div>';
    });
    el.innerHTML=h;
  }
  async function finishTask(t,score){
    try{
      var x=await sb.from('task_done').insert({task_id:t.id,score:score});
      if(x.error){toast(T('tAuthErr')+x.error.message,'oops');return}
      CL.done.push({task_id:t.id,uid:uid,score:score});addXp(t.xp);toast(T('tDone',{x:t.xp}),'cheer');renderCls();
    }catch(e){toast(T('tConnErr'),'oops')}
  }
  function taskResult(t,ok,n){if(ok/n>=.8)finishTask(t,ok);else toast(T('tFail'),'oops')}
  function doTask(t){
    if(t.kind!=='quiz'){finishTask(t,null);return}
    var src=String(t.words||'').split(/[\s,，、]+/).filter(function(h){return h&&hM(h)}).map(function(h){var l=hskLookup(h)||{};return {h:h,p:hP(h,l.p),m:hM(h)}});
    if(src.length<3){toast(T('tWords'),'oops');return}
    GM={mode:'mean',src:shuf(src),i:0,ok:0,all:gPool().all,task:t};
    showTab('play');$('plMenu').hidden=true;$('plGame').hidden=false;nextQ();
  }
  function askTask(cid,t){t=t||{};
    var title=prompt('Даалгаврын нэр',t.title||'');if(!title)return;
    var kind=prompt('Төрөл: quiz (үгийн тест) эсвэл free (чөлөөтэй)',t.kind||'quiz');if(kind===null)return;kind=kind.trim()==='free'?'free':'quiz';
    var words='';if(kind==='quiz'){words=prompt('Үгс таслалаар (жишээ: 爱,八,苹果)',t.words||'');if(words===null)return}
    var xp=prompt('XP',t.xp||20);if(xp===null)return;var due=prompt('Дуусах огноо YYYY-MM-DD (хоосон байж болно)',t.due||'');if(due===null)return;
    q(async function(){
      var pl={class_id:cid,title:title.trim(),kind:kind,words:words.trim(),xp:Math.max(1,+xp||20),due:/^\d{4}-\d{2}-\d{2}$/.test(due.trim())?due.trim():null};var r=t.id?await sb.from('tasks').update(pl).eq('id',t.id):await sb.from('tasks').insert(pl);
      if(r.error)throw r.error;refresh();
    });
  }
  document.addEventListener('click',function(e){
    var b=e.target.closest('[data-tdo]');
    if(b){var t=CL.tasks.filter(function(x){return x.id===b.dataset.tdo})[0];if(t)doTask(t);return}
    if(e.target.closest('#jcBtn')){
      var c=$('jcCode').value.trim();if(!c)return;
      q(async function(){var r=await sb.rpc('join_class',{p_code:c});if(r.error)throw r.error;refresh()});return;
    }
    if(!isOwner)return;
    if(e.target.closest('#clAdd')){
      var n=$('clName').value.trim();if(!n)return;
      var code='';for(var i=0;i<6;i++)code+='ABCDEFGHJKLMNPQRSTUVWXYZ23456789'[Math.floor(Math.random()*32)];
      q(async function(){var r=await sb.from('classes').insert({name:n,code:code});if(r.error)throw r.error;refresh()});return;
    }
    b=e.target.closest('[data-tedit]');
    if(b){var tt=CL.tasks.filter(function(x){return x.id===b.dataset.tedit})[0];if(tt)askTask(tt.class_id,tt);return}
    b=e.target.closest('[data-cmem]');if(b){clOpen[b.dataset.cmem]=!clOpen[b.dataset.cmem];renderClasses();return}
    b=e.target.closest('[data-mdel]');
    if(b){var pr=b.dataset.mdel.split('|');if(confirm('?'))q(async function(){var r=await sb.from('class_members').delete().eq('class_id',pr[0]).eq('uid',pr[1]);if(r.error)throw r.error;refresh()});return}
    b=e.target.closest('[data-tnew]');if(b){askTask(b.dataset.tnew);return}
    b=e.target.closest('[data-tdel]');
    if(b&&confirm('?'))q(async function(){var r=await sb.from('tasks').delete().eq('id',b.dataset.tdel);if(r.error)throw r.error;refresh()});
  });
  /* ---------- зурж хайх: хайлтын логик (UI нь js/hw-lite.js-д) ---------- */
  window.HWL=window.HWL||{};
  window.HWL.lookup=function(q){
    var out=[],seen={};
    [HSKRAW].forEach(function(R){LEVELS.forEach(function(lv){(R[lv]||'').split(',').forEach(function(it){
      var p=it.split('|'),h=p[0];if(!h||h.indexOf(q)<0||seen[h])return;seen[h]=1;
      out.push({h:h,p:hP(h,p[1]),m:hM(h),l:lv,x:h===q?1:0})})})});
    out.sort(function(x,y){return (y.x-x.x)||(x.h.length-y.h.length)||(x.l-y.l)});
    if(!out.length)return '<div class="hint">'+esc(window.HWL.t?window.HWL.t('hwNone'):'—')+'</div>';
    return '<div class="list">'+out.slice(0,20).map(function(x){
      return '<div class="w"><span class="h" lang="zh">'+hl(x.h,q)+'</span><span><span class="p">'+esc(x.p)+'</span> <span class="badge">HSK '+x.l+'</span><br><span class="m">'+(x.m?esc(x.m):'<span class="hint">'+T('hskNoTr')+'</span>')+'</span></span><span><button class="btn small ghost" type="button" data-speak="'+esc(x.h)+'" aria-label="Audio">🔊</button></span></div>'}).join('')+'</div>';
  };
  if(window.HWL.ready)window.HWL.ready();
  /* ---------- beginner course ---------- */
  CI18N=DATA.CI18N||null;
  LESSONS=DATA.LESSONS,lrnOpen=-1;
  function lrnDoneArr(){return (S.profile&&S.profile.lrn)||[]}
  /* ---------- pinyin -> Cyrillic (Palladius-style, approximate) ---------- */
  var PY_INIT=['zh','ch','sh','b','p','m','f','d','t','n','l','g','k','h','j','q','x','r','z','c','s','y','w'];
  var PY_FIN=['iang','iong','uang','ang','eng','ing','ong','ian','iao','uai','uan','üan','ia','ie','iu','ua','uo','ui','un','üe','ün','ai','ei','ao','ou','an','en','in','er','a','o','e','i','u','ü'];
  var CY_INIT={b:'б',p:'п',m:'м',f:'ф',d:'д',t:'т',n:'н',l:'л',g:'г',k:'к',h:'х',j:'цз',q:'ц',x:'с',zh:'чж',ch:'ч',sh:'ш',r:'ж',z:'цз',c:'ц',s:'с'};
  var CY_FIN={a:'а',o:'о',e:'э',i:'и',u:'у','ü':'юй',ai:'ай',ei:'эй',ao:'ао',ou:'оу',an:'ань',en:'энь',ang:'ан',eng:'эн',ong:'ун',er:'эр',ia:'я',ie:'е',iao:'яо',iu:'ю',ian:'янь',in:'инь',iang:'ян',ing:'ин',iong:'юн',ua:'уа',uo:'о',uai:'уай',ui:'уй',uan:'уань',un:'унь',uang:'уан','üe':'юэ','üan':'юань','ün':'юнь'};
  var CY_Y={a:'я',e:'е',ao:'яо',ou:'ю',an:'янь',in:'инь',ang:'ян',ing:'ин',ong:'юн',i:'и','ü':'юй','üe':'юэ','üan':'юань','ün':'юнь',o:'ё'};
  var CY_W={a:'ва',o:'во',ai:'вай',ei:'вэй',an:'вань',en:'вэнь',ang:'ван',eng:'вэн',u:'у'};
  var PY_TONE={'ā':'a','á':'a','ǎ':'a','à':'a','ē':'e','é':'e','ě':'e','è':'e','ī':'i','í':'i','ǐ':'i','ì':'i','ō':'o','ó':'o','ǒ':'o','ò':'o','ū':'u','ú':'u','ǔ':'u','ù':'u','ǖ':'ü','ǘ':'ü','ǚ':'ü','ǜ':'ü','v':'ü'};
  function cyrSyl(i,f){
    if(i==='y')return CY_Y[f]||null;
    if(i==='w')return CY_W[f]||null;
    if(!i)return CY_FIN[f]||null;
    var b=CY_INIT[i];if(!b)return null;
    if(f==='i'){if('zh ch sh r'.split(' ').indexOf(i)>-1)return b+'и';if('z c s'.split(' ').indexOf(i)>-1)return b+'ы';return b+'и'}
    if(f==='ui')return b+(i==='h'?'уэй':'уй');
    if('jqx'.indexOf(i)>-1&&f==='u')f='ü';
    var r=CY_FIN[f];if(!r)return null;
    if(f==='ü'&&'jqx'.indexOf(i)<0)r='юй';
    return b+r;
  }
  function pySeg(s){
    var memo={};
    function go(k,first){
      var key=k+'|'+first;if(memo[key]!==undefined)return memo[key];
      if(k===s.length)return (memo[key]={c:0,a:[]});
      var best=null,rest=s.slice(k);
      PY_INIT.concat(['']).forEach(function(ini){
        if(ini&&rest.indexOf(ini)!==0)return;
        var r2=rest.slice(ini.length);
        PY_FIN.forEach(function(fin){
          if(r2.indexOf(fin)!==0)return;
          var sub=go(k+ini.length+fin.length,false);if(!sub)return;
          var c=1+sub.c+((!ini&&!first)?10:0);
          if(!best||c<best.c)best={c:c,a:[[ini,fin]].concat(sub.a)};
        });
      });
      return (memo[key]=best||null);
    }
    return go(0,true);
  }
  function pyCyr(py){
    var out=[],ok=true;
    String(py||'').toLowerCase().split(/[\s,，、.。?？!！…·]+/).forEach(function(tok){
      if(!tok)return;
      var parts=tok.split(/['’-]/),res=[];
      parts.forEach(function(p){
        if(!p)return;
        var pl=Array.from(p).map(function(c){return PY_TONE[c]||c}).join('').replace(/([jqxy])u(?=e|an|n|$)/g,'$1ü');
        if(!/^[a-zü]+$/.test(pl)){ok=false;return}
        var sg=pySeg(pl);if(!sg){ok=false;return}
        sg.a.forEach(function(x){var c=cyrSyl(x[0],x[1]);if(c==null)ok=false;else res.push(c)});
      });
      if(res.length)out.push(res.join('-'));
    });
    return ok&&out.length?out.join(' '):'';
  }

